/**
 * Approved oncology therapeutics wave 1 (September 2026): every product on the NCI "A to Z List of Cancer
 * Drugs" (src/data/universe-lists/nci-cancer-drugs.json) and every EMA-authorised oncology medicine that the
 * corpus lacked. Facts come from the US prescribing information (DailyMed / Drugs@FDA), the NCI drug page and
 * the EMA EPAR; approval years are the original Drugs@FDA action dates. Supportive-care agents carry the tag
 * "supportive". Records are deliberately compact: what it is, who it helps, where it is approved.
 *
 * Registered in src/data/index.ts as `approvedWave1`. Targets and companies added for these records live in
 * targets-wave1.ts and companies-wave1.ts.
 */
import type { DrugInput } from "@/lib/schema";

