const batch2: DrugInput[] = [
  d({ id: "thiotepa", name: "Thiotepa", brand: "Tepadina", aka: ["Thioplex (historic)", "Triethylenethiophosphoramide"], modality: "Alkylating agent (ethylenimine)", mechanism: "Polyfunctional alkylating agent related to nitrogen mustard; releases ethyleneimine radicals that cross-link DNA. Crosses the blood-brain barrier, which underlies its use in CNS lymphoma conditioning.", wikipedia: W("Thiotepa"),
    tldr: "Thiotepa is an old chemotherapy with a modern job: at high doses it prepares patients for stem cell transplants, and it is still instilled into the bladder or body cavities for superficial bladder cancer and malignant effusions.",
    summary: "Thiotepa was first approved in 1959 for adenocarcinoma of the breast or ovary, superficial papillary carcinoma of the urinary bladder and control of malignant intracavitary effusions. Tepadina (approved 2017 in the US, 2010 in the EU) added conditioning before allogeneic haematopoietic stem cell transplantation, initially for children with class 3 beta-thalassaemia in the US and, in the EU, for haematological and solid tumours in adults and children. In practice thiotepa-based regimens (TBC, thiotepa-busulfan-fludarabine) are standard before autologous transplant in primary CNS lymphoma and in cord blood and haploidentical transplantation. Profound myelosuppression, mucositis and skin toxicity from sweat excretion (patients bathe frequently) are the main issues.",
    approvals: [{ region: "US", year: 1959, indication: "Breast and ovarian adenocarcinoma; superficial papillary bladder carcinoma (intravesical); malignant effusions" }, { region: "US", year: 2017, indication: "Conditioning before allogeneic HSCT for class 3 beta-thalassaemia in children (Tepadina)" }, { region: "EU", year: 2010, indication: "Conditioning before haematopoietic progenitor cell transplantation for haematological diseases and solid tumours (Tepadina)" }],
    cancers: ["urothelial", "breast-hr-positive", "ovarian", "primary-cns-lymphoma"], companies: ["adienne"], technologies: ["cytotoxic-chemotherapy", "allogeneic-hsct", "autologous-stem-cell-transplant", "bcg-and-intravesical-therapy"], links: label("thiotepa", "thiotepa", [{ label: "EPAR (Tepadina)", url: EPAR("tepadina") }]), tags: ["nci-list"] }),
  d({ id: "trametinib", name: "Trametinib", brand: "Mekinist", modality: "Small-molecule allosteric MEK1/2 inhibitor", mechanism: "Reversible, non-ATP-competitive inhibitor of MEK1 and MEK2 kinase activity and activation, blocking ERK phosphorylation downstream of BRAF.", wikipedia: W("Trametinib"),
    tldr: "Trametinib (Mekinist) blocks MEK, the protein one step below BRAF in the growth-signal chain. Paired with dabrafenib it treats BRAF-mutant melanoma, lung, thyroid and other cancers, including brain tumours in children.",
    summary: "Trametinib was approved by the FDA in May 2013 as a single agent for BRAF V600E or V600K metastatic melanoma (METRIC: progression-free survival superior to chemotherapy) and in January 2014 in combination with dabrafenib, the pairing that became standard after COMBI-d and COMBI-v. All later indications are with dabrafenib: adjuvant stage III melanoma (COMBI-AD), BRAF V600E metastatic NSCLC, anaplastic thyroid cancer, tumour-agnostic BRAF V600E solid tumours and paediatric low-grade glioma with an oral solution (2023). The EU authorised Mekinist in 2014. Rash, diarrhoea, reduced ejection fraction, retinal vein occlusion and central serous retinopathy are the MEK-class toxicities; pyrexia dominates the combination.",
    approvals: [{ region: "US", year: 2013, indication: "BRAF V600E/K unresectable or metastatic melanoma (single agent)" }, { region: "US", year: 2014, indication: "With dabrafenib: metastatic melanoma; later adjuvant melanoma, NSCLC, anaplastic thyroid cancer, tumour-agnostic BRAF V600E solid tumours, paediatric low-grade glioma" }, { region: "EU", year: 2014, indication: "BRAF V600 melanoma alone or with dabrafenib; later NSCLC and adjuvant melanoma" }],
    targets: ["mek"], cancers: ["melanoma", "nsclc", "thyroid", "anaplastic-thyroid-cancer", "low-grade-serous-ovarian-cancer"], companies: ["novartis"], technologies: ["kinase-inhibitors"], trials: ["combi-ad", "nct04940052", "nct05372354", "nct05358249", "nct04417621", "nct03899155", "nct05874414"], related: ["dabrafenib", "dabrafenib-trametinib"], pathways: ["ras-mapk"], links: label("trametinib", "trametinib", [{ label: "EPAR", url: EPAR("mekinist") }]), tags: ["nci-list"] }),
  d({ id: "valrubicin", name: "Valrubicin", brand: "Valstar", modality: "Anthracycline (intravesical)", mechanism: "Semi-synthetic anthracycline analogue of doxorubicin instilled into the bladder; inhibits nucleoside incorporation into nucleic acids and topoisomerase II, arresting cells in G2.", wikipedia: W("Valrubicin"),
    tldr: "Valrubicin (Valstar) is a chemotherapy washed into the bladder for carcinoma in situ that has not responded to BCG, in patients who cannot yet have their bladder removed.",
    summary: "Valrubicin was approved in September 1998 for intravesical therapy of BCG-refractory carcinoma in situ of the urinary bladder in patients for whom immediate cystectomy would carry unacceptable morbidity or mortality. In the pivotal experience, 230 patients received the drug and about one in five with refractory CIS had a complete response, mostly not durable, so it is a bridge rather than a cure; the label stresses that delaying cystectomy risks progression. Newer options for BCG-unresponsive disease (pembrolizumab, nadofaragene firadenovec, nogapendekin alfa inbakicept, TAR-200) have reduced its use. Irritative bladder symptoms and red-tinged urine are expected.",
    approvals: [{ region: "US", year: 1998, indication: "Intravesical therapy of BCG-refractory carcinoma in situ of the bladder when immediate cystectomy is not acceptable" }],
    cancers: ["urothelial"], technologies: ["bcg-and-intravesical-therapy", "topoisomerase-inhibitors"], related: ["nadofaragene-firadenovec", "nogapendekin-alfa"], companies: ["endo"], links: label("valrubicin", "valrubicin"), tags: ["nci-list"] }),
  d({ id: "vorinostat", name: "Vorinostat", brand: "Zolinza", aka: ["SAHA", "Suberoylanilide hydroxamic acid"], modality: "Small-molecule pan-HDAC inhibitor (hydroxamate)", mechanism: "Inhibits class I (HDAC1, 2, 3) and class II (HDAC6) histone deacetylases at nanomolar concentrations, causing histone hyperacetylation, re-expression of silenced genes, cell-cycle arrest and apoptosis.", wikipedia: W("Vorinostat"),
    tldr: "Vorinostat (Zolinza) was the first drug of its kind, a capsule that loosens the chemical packaging of DNA. It treats the skin disease of cutaneous T-cell lymphoma after two other treatments have failed.",
    summary: "Vorinostat was approved by the FDA in October 2006 for cutaneous manifestations of cutaneous T-cell lymphoma in patients with progressive, persistent or recurrent disease on or after two systemic therapies, on two open-label studies (response rate about 30% in the pivotal single-arm study of 74 patients). It was the first histone deacetylase inhibitor approved for any cancer and remains a standard option in refractory mycosis fungoides and Sezary syndrome; a European application was withdrawn and it is not authorised in the EU. Fatigue, diarrhoea, thrombocytopenia, taste change and QT prolongation are the main adverse effects; thromboembolism is a class warning.",
    approvals: [{ region: "US", year: 2006, indication: "Cutaneous manifestations of CTCL with progressive, persistent or recurrent disease after two systemic therapies" }],
    targets: ["hdac"], companies: ["merck"], technologies: ["epigenetic-drugs"], related: ["romidepsin", "bexarotene"], links: label("vorinostat", "vorinostat"), tags: ["nci-list"], notes: ["Cutaneous T-cell lymphoma has no cancer record yet."] }),
  d({ id: "nilutamide", name: "Nilutamide", brand: "Nilandron", aka: ["Anandron"], modality: "Non-steroidal antiandrogen (first generation)", mechanism: "Competitive androgen receptor antagonist without oestrogenic, progestational or glucocorticoid activity.", wikipedia: W("Nilutamide"),
    tldr: "Nilutamide (Nilandron) is an older antiandrogen tablet started on the day of surgical castration for metastatic prostate cancer; it is rarely used now because of lung and eye side effects.",
    summary: "Nilutamide was approved in 1996 for metastatic (stage D2) prostate cancer in combination with surgical castration, with treatment beginning on the day of or the day after orchiectomy, on a randomised trial in which the combination modestly delayed progression compared with castration alone. It has been superseded by bicalutamide and the second-generation antiandrogens. Interstitial pneumonitis (about 2% of patients, more in Japanese men) carries a boxed warning; delayed dark adaptation, alcohol intolerance and hepatitis are also characteristic.",
    approvals: [{ region: "US", year: 1996, indication: "Metastatic (stage D2) prostate cancer in combination with surgical castration" }],
    targets: ["androgen-receptor"], cancers: ["prostate"], technologies: ["androgen-deprivation"], related: ["flutamide", "bicalutamide"], links: label("nilutamide", "nilutamide"), tags: ["nci-list", "generic"] }),
  d({ id: "toremifene", name: "Toremifene", brand: "Fareston", modality: "Selective oestrogen receptor modulator (triphenylethylene)", mechanism: "Chlorinated tamoxifen analogue that binds the oestrogen receptor and acts as an antagonist in breast tissue with partial agonist effects elsewhere.", wikipedia: W("Toremifene"),
    tldr: "Toremifene (Fareston) is a tamoxifen-like tablet for postmenopausal women with hormone-sensitive breast cancer that has spread.",
    summary: "Toremifene was approved by the FDA in May 1997 for metastatic breast cancer in postmenopausal women with oestrogen receptor-positive or unknown tumours, on three randomised trials (North American, Eastern European and Nordic) that showed response rates and time to progression similar to tamoxifen; the EU authorised Fareston in 1996 for first-line hormonal treatment of hormone-dependent metastatic breast cancer. It never displaced tamoxifen and aromatase inhibitors then moved ahead of both. QT prolongation carries a boxed warning; hot flushes, sweating and vaginal discharge are the common effects, with thromboembolism and endometrial changes as class risks.",
    approvals: [{ region: "US", year: 1997, indication: "Metastatic breast cancer in postmenopausal women with ER-positive or unknown tumours" }, { region: "EU", year: 1996, indication: "First-line hormonal treatment of hormone-dependent metastatic breast cancer in postmenopausal women" }],
    targets: ["estrogen-receptor"], cancers: ["breast-hr-positive"], companies: ["kyowa-kirin"], technologies: ["endocrine-therapy"], related: ["tamoxifen"], links: label("toremifene", "toremifene", [{ label: "EPAR", url: EPAR("fareston") }]), tags: ["nci-list"] }),
  d({ id: "raloxifene", trials: ["nct06062810"], name: "Raloxifene", brand: "Evista", modality: "Selective oestrogen receptor modulator (benzothiophene)", mechanism: "Oestrogen receptor agonist in bone and antagonist in breast and uterus; lowers the incidence of ER-positive invasive breast cancer.", wikipedia: W("Raloxifene"),
    tldr: "Raloxifene (Evista) is an osteoporosis tablet that also lowers the chance of developing invasive breast cancer in postmenopausal women at higher risk, with fewer womb-cancer problems than tamoxifen.",
    summary: "Raloxifene was approved in December 1997 for treatment and prevention of postmenopausal osteoporosis and in September 2007 for reduction in the risk of invasive breast cancer in postmenopausal women with osteoporosis or at high risk of breast cancer, on the MORE, CORE and RUTH trials and the head-to-head STAR trial (NSABP P-2), in which raloxifene was about as effective as tamoxifen against invasive breast cancer with fewer uterine cancers and thromboembolic events but less protection against non-invasive disease. It does not treat breast cancer or reduce recurrence. Venous thromboembolism and fatal stroke in women with coronary disease carry a boxed warning.",
    approvals: [{ region: "US", year: 1997, indication: "Treatment and prevention of postmenopausal osteoporosis" }, { region: "US", year: 2007, indication: "Reduction in risk of invasive breast cancer in postmenopausal women with osteoporosis or at high risk" }],
    targets: ["estrogen-receptor"], cancers: ["breast-hr-positive"], companies: ["eli-lilly"], technologies: ["chemoprevention", "endocrine-therapy"], related: ["tamoxifen"], links: label("raloxifene", "raloxifenehydrochloride"), tags: ["nci-list", "prevention"] }),
  d({ id: "triptorelin", name: "Triptorelin", brand: "Trelstar", aka: ["Decapeptyl", "Triptodur (paediatric)"], modality: "GnRH agonist depot", mechanism: "Synthetic decapeptide GnRH agonist; continuous stimulation desensitises pituitary GnRH receptors, suppressing LH and testosterone to castrate levels after an initial surge.", wikipedia: W("Triptorelin"),
    tldr: "Triptorelin (Trelstar) is a one-, three- or six-monthly injection that switches off testosterone production for men with advanced prostate cancer.",
    summary: "Triptorelin pamoate was approved by the FDA in June 2000 (3.75 mg monthly), with 11.25 mg three-monthly (2001) and 22.5 mg six-monthly (2010) depots following, for palliative treatment of advanced prostate cancer; the pivotal randomised trial of 277 men showed castrate testosterone suppression comparable to leuprolide. As Decapeptyl it has been used in Europe since the 1980s for prostate cancer, endometriosis and, in premenopausal breast cancer, for ovarian function suppression in the SOFT and TEXT trials that established the combination with exemestane. Hot flushes, loss of bone density, metabolic effects and initial flare (covered with an antiandrogen) are shared with the class.",
    approvals: [{ region: "US", year: 2000, indication: "Palliative treatment of advanced prostate cancer" }],
    targets: ["androgen-receptor"], cancers: ["prostate", "breast-hr-positive"], companies: ["verity-pharma", "ipsen"], technologies: ["androgen-deprivation", "endocrine-therapy"], related: ["leuprolide", "goserelin"], links: label("triptorelin", "triptorelin-pamoate"), tags: ["nci-list"] }),
  d({ id: "dexamethasone", trials: ["nct04442022", "nct06868654", "nct05730036", "nct06464991", "nct06305754", "nct06956170", "nct05438043", "nct05572515", "nct05623020", "nct06152575", "nct03539744", "nct05519085", "nct06824467", "nct04975997", "nct06413498", "nct06158841", "nct06230224", "nct05020236", "nct07095452", "nct06208150", "nct06679101", "nct06868667", "nct05552976", "nct05552222", "nct05455320", "nct02343042", "nct03314181", "nct05372354", "nct04414475", "nct07284758", "nct04133636", "nct05583617", "nct03989414", "nct04068597", "nct06988488", "nct06087653", "nct07150091", "nct06892522", "nct06953960", "nct05704049", "nct07227311", "nct07018050", "nct06106945", "nct02899052", "nct05714839", "nct04973605", "nct02773030", "nct07150104", "nct05663866", "nct06979596", "nct04270409", "nct07742215", "nct05319730", "nct06353386", "nct07387926", "nct06788912"], regulatoryEvents: [{ date: "2026-08-13", type: "approval", region: "US", note: "FDA grants accelerated approval to iberdomide with daratumumab and hyaluronidase-fihj and dexamethasone for multiple myeloma", source: "https://www.fda.gov/drugs/resources-information-approved-drugs/fda-grants-accelerated-approval-iberdomide-daratumumab-and-hyaluronidase-fihj-and-dexamethasone" }], name: "Dexamethasone", brand: "Decadron (historic) / Hemady / Neofordex", modality: "Glucocorticoid", mechanism: "Synthetic glucocorticoid receptor agonist; lympholytic in leukaemia, lymphoma and myeloma, anti-inflammatory and antiemetic through genomic and non-genomic actions.", wikipedia: W("Dexamethasone"),
    tldr: "Dexamethasone is a long-acting glucocorticoid steroid that kills lymphoid cancer cells directly, which is why it sits in nearly every myeloma regimen and in childhood leukaemia and lymphoma protocols. It is also the standard drug for preventing chemotherapy sickness and for brain swelling and spinal cord compression; high blood sugar, insomnia, muscle wasting and infection follow prolonged use.",
    summary: "Dexamethasone was approved in 1958 and is labelled for palliative management of leukaemias and lymphomas among dozens of inflammatory indications; in oncology it is the steroid of virtually every multiple myeloma regimen (with bortezomib, lenalidomide, daratumumab and the newer antibodies), of paediatric ALL induction where it replaced prednisone in several protocols, and of the R-CHOP-like and hyper-CVAD regimens. Hemady (20 mg tablets, 2019) is a US product labelled specifically for multiple myeloma, and Neofordex (40 mg tablets) was authorised in the EU in 2016 for the same disease. It is also first-line antiemetic prophylaxis, the standard for tumour-associated brain oedema and spinal cord compression, and a premedication for taxanes and pemetrexed. Hyperglycaemia, insomnia, myopathy, infection and adrenal suppression follow prolonged use.",
    approvals: [{ region: "US", year: 1958, indication: "Palliative management of leukaemias and lymphomas; inflammatory and allergic conditions" }, { region: "US", year: 2019, indication: "Multiple myeloma in combination with other antimyeloma products (Hemady)" }, { region: "EU", year: 2016, indication: "Multiple myeloma in combination (Neofordex)" }],
    cancers: ["multiple-myeloma", "all-leukemia", "dlbcl", "hodgkin-lymphoma"], technologies: ["antiemetic-therapy"], links: label("dexamethasone", "dexamethasone", [{ label: "EPAR (Neofordex)", url: EPAR("neofordex") }]), tags: ["nci-list", "generic", "supportive"], terms: ["bone-metastases"] }),
  d({ id: "prednisone", trials: ["nct06097364", "nct04529772", "nct06717347", "nct06191744", "nct03706365", "nct04446117", "nct06091865", "nct06091254", "nct06925737", "nct04691804", "nct04663347", "nct06689163", "nct04542824", "nct02960022", "nct07124936", "nct05201248", "nct06568094", "nct07730515", "nct07005154", "nct05067140", "nct05283720", "nct06564038", "nct07553988", "nct02257736", "nct05288166", "nct03431350", "nct05406401", "nct07225946", "nct06353386", "nct04623541", "nct06890884", "nct04497844", "nct05673785", "nct04980222", "nct06947967", "nct06425302"], regulatoryEvents: [{ date: "2026-06-12", type: "approval", region: "US", note: "FDA approves capivasertib with abiraterone and prednisone for PTEN-deficient androgen pathway modulation-naïve or -sensitive prostate cancer", source: "https://www.fda.gov/drugs/resources-information-approved-drugs/fda-approves-capivasertib-abiraterone-and-prednisone-pten-deficient-androgen-pathway-modulation" }], name: "Prednisone", brand: "Deltasone (historic) / Rayos", aka: ["Prednisolone (active metabolite, used in the UK and Europe)"], modality: "Glucocorticoid", mechanism: "Prodrug converted in the liver to prednisolone, a glucocorticoid receptor agonist that is lympholytic and anti-inflammatory.", wikipedia: W("Prednisone"),
    tldr: "Prednisone is the everyday steroid tablet in cancer care. It is the P in CHOP and MOPP for lymphoma, part of childhood leukaemia treatment, and taken with abiraterone in prostate cancer.",
    summary: "Prednisone was approved in 1955 and its label lists leukaemias and lymphomas for palliative management and hypercalcaemia of malignancy alongside a long list of inflammatory conditions. In oncology it is a component of R-CHOP (diffuse large B-cell lymphoma), MOPP and BEACOPP (Hodgkin lymphoma), childhood and adult ALL induction and CLL regimens, and it is co-prescribed with abiraterone to prevent mineralocorticoid excess and with docetaxel in metastatic castration-resistant prostate cancer. It also treats immune-related adverse events of checkpoint inhibitors and is used in palliative care for appetite and fatigue. Prednisolone is the equivalent used in the UK and much of Europe. Long-term use brings hyperglycaemia, osteoporosis, infection risk, mood change and adrenal suppression.",
    approvals: [{ region: "US", year: 1955, indication: "Palliative management of leukaemias and lymphomas; hypercalcaemia of malignancy; inflammatory conditions" }],
    cancers: ["dlbcl", "hodgkin-lymphoma", "all-leukemia", "cll", "prostate"], related: ["abiraterone", "docetaxel"], links: label("prednisone", "prednisone"), tags: ["nci-list", "generic", "supportive"], terms: ["prodrug"] }),
  d({ id: "imiquimod", name: "Imiquimod", brand: "Aldara / Zyclara", modality: "Topical immune response modifier (TLR7 agonist)", mechanism: "Toll-like receptor 7 agonist that induces interferon-alpha, TNF and other cytokines from dendritic cells and macrophages; the label states the mechanism in basal cell carcinoma and actinic keratosis is not fully established.", wikipedia: W("Imiquimod"),
    tldr: "Imiquimod (Aldara) is a cream that provokes the skin's own immune system to clear superficial basal cell carcinomas and the sun-damage patches (actinic keratoses) that can turn into skin cancer.",
    summary: "Imiquimod 5% cream was approved in 1997 for external genital warts and in 2004 for actinic keratosis and for superficial basal cell carcinoma up to 2 cm in immunocompetent adults when surgery is less appropriate, on vehicle-controlled trials with histological clearance in about three-quarters of treated sBCC lesions. Zyclara 2.5% and 3.75% (2010) offers a shorter field regimen for actinic keratosis. The EU authorised Aldara in 1998 with the same three indications. It is applied five times a week for six weeks for sBCC; local inflammation, erosion and flu-like symptoms are expected and predict response. Long-term recurrence is higher than after excision, so it is reserved for low-risk lesions.",
    approvals: [{ region: "US", year: 1997, indication: "External genital and perianal warts" }, { region: "US", year: 2004, indication: "Actinic keratosis; superficial basal cell carcinoma in immunocompetent adults" }, { region: "EU", year: 1998, indication: "Genital warts, superficial basal cell carcinoma and actinic keratosis (Aldara)" }],
    cancers: ["basal-cell-carcinoma", "cutaneous-scc"], companies: ["bausch-health"], technologies: ["chemoprevention"], links: label("imiquimod", "imiquimod", [{ label: "EPAR (Aldara)", url: EPAR("aldara") }]), tags: ["nci-list"], terms: ["histology"] }),
  d({ id: "aminolevulinic-acid", trials: ["nct07225621", "nct05736406"], name: "Aminolevulinic acid (topical, for photodynamic therapy)", brand: "Levulan Kerastick / Ameluz", aka: ["5-ALA", "ALA HCl"], modality: "Topical porphyrin precursor for photodynamic therapy", mechanism: "Taken up by dysplastic keratinocytes and converted to protoporphyrin IX, which on illumination with blue (Levulan) or red (Ameluz) light generates singlet oxygen and destroys the lesion.", wikipedia: W("Aminolevulinic_acid"),
    tldr: "Aminolevulinic acid is painted on sun-damaged skin and then activated with a lamp, destroying actinic keratoses before they can become skin cancer; in Europe the gel is also approved for superficial basal cell carcinoma.",
    summary: "Levulan Kerastick (aminolevulinic acid 20% solution) with BLU-U blue light was approved in December 1999 for actinic keratoses of the face and scalp; Ameluz (10% nanoemulsion gel) with the BF-RhodoLED red lamp followed in May 2016 for lesion- and field-directed treatment of mild to moderate actinic keratosis, on three randomised trials with complete clearance in the majority of patients. The EU authorised Ameluz in 2011 and extended it in 2017 to superficial and nodular basal cell carcinoma unsuitable for surgery. Photodynamic therapy is a field treatment for precancerous skin; pain during illumination and local erythema are expected. Oral aminolevulinic acid (Gleolan) for fluorescence-guided glioma surgery is an imaging agent covered elsewhere.",
    approvals: [{ region: "US", year: 1999, indication: "Actinic keratoses of the face and scalp with blue-light photodynamic therapy (Levulan Kerastick)" }, { region: "US", year: 2016, indication: "Mild to moderate actinic keratosis of face and scalp with red-light PDT (Ameluz)" }, { region: "EU", year: 2011, indication: "Actinic keratosis; superficial and nodular basal cell carcinoma added 2017 (Ameluz)" }],
    cancers: ["cutaneous-scc", "basal-cell-carcinoma"], companies: ["biofrontera", "sun-pharma", "photonamic"], technologies: ["precancer-ablation"], links: label("aminolevulinic acid", "aminolevulinicacid", [{ label: "EPAR (Ameluz)", url: EPAR("ameluz") }]), tags: ["nci-list", "prevention"] }),
  d({ id: "denileukin-diftitox", name: "Denileukin diftitox", brand: "Lymphir", aka: ["Ontak (1999 to 2014)", "E7777"], modality: "IL-2 receptor-directed cytotoxin (fusion protein)", mechanism: "Fusion of interleukin-2 with diphtheria toxin fragments A and B; binds CD25-expressing cells, is internalised, and the toxin blocks protein synthesis and kills the cell.", wikipedia: W("Denileukin_diftitox"),
    tldr: "Denileukin diftitox (Lymphir) is an infusion that uses the interleukin-2 signal as a homing device to deliver a bacterial toxin into cutaneous T-cell lymphoma cells. It was withdrawn in 2014 and returned in an improved form in 2024.",
    summary: "The original denileukin diftitox (Ontak) was approved in 1999 for persistent or recurrent CD25-positive cutaneous T-cell lymphoma and withdrawn from the US market in 2014 because of manufacturing problems. A reformulated, higher-purity product was approved by the FDA in August 2024 as Lymphir for adults with relapsed or refractory stage I to III CTCL after at least one systemic therapy, on Study 302, an open-label single-arm trial in which 36% of patients responded (with CD25 expression on at least 20% of malignant cells required for entry). Capillary leak syndrome, infusion reactions and visual changes carry boxed warnings and require premedication and close monitoring.",
    approvals: [{ region: "US", year: 1999, indication: "Persistent or recurrent CD25-positive CTCL (Ontak; withdrawn 2014)" }, { region: "US", year: 2024, indication: "Relapsed or refractory stage I to III CTCL after at least one systemic therapy (Lymphir)" }],
    targets: ["cd25"], companies: ["citius-pharmaceuticals", "eisai"], links: label("denileukin diftitox", "denileukindiftitox-cxdl"), tags: ["nci-list"], notes: ["Cutaneous T-cell lymphoma has no cancer record yet."] }),
  d({ id: "ibritumomab-tiuxetan", name: "Ibritumomab tiuxetan", brand: "Zevalin", aka: ["Y-90 ibritumomab", "Zevalin therapeutic regimen"], modality: "Radioimmunotherapy (yttrium-90 labelled anti-CD20 antibody)", mechanism: "Murine anti-CD20 IgG1 (the parent of rituximab) chelated via tiuxetan to yttrium-90; beta emission delivers radiation to CD20-positive B cells and neighbouring tumour cells (crossfire), given after rituximab to clear circulating B cells.", wikipedia: W("Ibritumomab_tiuxetan"),
    tldr: "Zevalin is an antibody carrying a radioactive isotope that seeks out CD20 on lymphoma cells. It treats follicular lymphoma that has relapsed and is given as a one-off consolidation after chemotherapy.",
    summary: "Ibritumomab tiuxetan was the first radioimmunotherapy approved by the FDA, in February 2002, for relapsed or refractory low-grade, follicular or transformed B-cell non-Hodgkin lymphoma including rituximab-refractory disease (Study 106-06: response in a majority of 54 rituximab-refractory patients), and in 2009 for consolidation after first-line chemotherapy in follicular lymphoma with a response (FIT trial: prolonged progression-free survival). The EU authorised Zevalin in 2004. Despite efficacy and a single-day treatment, use collapsed because of logistics between nuclear medicine and haematology, prolonged cytopenias and competition from rituximab maintenance and later agents; tositumomab (Bexxar) was discontinued in 2014. Severe cytopenias and infusion reactions carry boxed warnings.",
    approvals: [{ region: "US", year: 2002, indication: "Relapsed or refractory low-grade, follicular or transformed B-cell NHL including rituximab-refractory follicular lymphoma" }, { region: "US", year: 2009, indication: "Consolidation after first-line chemotherapy in previously untreated follicular NHL" }, { region: "EU", year: 2004, indication: "Rituximab-relapsed or refractory CD20-positive follicular lymphoma; first-line consolidation added 2008" }],
    targets: ["cd20"], cancers: ["follicular-lymphoma"], companies: ["acrotech-biopharma"], technologies: ["radioimmunotherapy", "monoclonal-antibody"], related: ["rituximab"], links: label("ibritumomab tiuxetan", "ibritumomabtiuxetan", [{ label: "EPAR", url: EPAR("zevalin") }]), tags: ["nci-list"] }),
  d({ id: "iobenguane-i-131", name: "Iobenguane I-131 (therapeutic)", brand: "Azedra", aka: ["131I-MIBG", "Ultratrace iobenguane"], modality: "Radiopharmaceutical therapy (beta and gamma emitter)", mechanism: "Noradrenaline analogue taken up by the noradrenaline transporter into chromaffin and neuroendocrine tumour cells; iodine-131 beta emission delivers targeted radiation.", wikipedia: W("Iobenguane"),
    tldr: "Azedra was a radioactive drug that homed in on adrenal-type tumours (phaeochromocytoma and paraganglioma) that could not be removed and delivered radiation from inside. It was approved in 2018 and discontinued by its maker in 2024.",
    summary: "High-specific-activity iobenguane I-131 (Azedra) was approved by the FDA in July 2018 for adults and children aged 12 and over with iobenguane scan-positive, unresectable, locally advanced or metastatic phaeochromocytoma or paraganglioma requiring systemic therapy, on a single-arm phase 2 study in which a quarter of patients halved their antihypertensive medication for at least six months and most had tumour control. It was the first approved therapy for these tumours. Progenics (later Lantheus) discontinued manufacture in 2024, so patients rely on compounded low-specific-activity 131I-MIBG or lutetium-177 dotatate. Myelosuppression, secondary MDS and leukaemia, hypothyroidism and renal toxicity were the main risks; the diagnostic-dose iobenguane (AdreView) is an imaging agent covered separately.",
    approvals: [{ region: "US", year: 2018, indication: "Iobenguane scan-positive unresectable, locally advanced or metastatic phaeochromocytoma or paraganglioma in patients 12 and older (discontinued 2024)" }],
    status: "withdrawn", cancers: ["neuroendocrine"], companies: ["lantheus"], technologies: ["mibg-theranostics", "radioligand-therapy"], related: ["lutathera"], links: label("iobenguane", "iobenguanei131"), tags: ["nci-list"], notes: ["Phaeochromocytoma and paraganglioma have no cancer record yet; linked to neuroendocrine tumours."], terms: ["radioiodine-term"] }),
  d({ id: "necitumumab", trials: ["nct03944772"], name: "Necitumumab", brand: "Portrazza", modality: "Monoclonal antibody (anti-EGFR, IgG1)", mechanism: "Fully human IgG1 that binds the EGFR ligand-binding domain, blocking ligand-induced activation and downstream MAPK and PI3K signalling.", wikipedia: W("Necitumumab"),
    tldr: "Necitumumab (Portrazza) is an antibody added to gemcitabine and cisplatin as first treatment for squamous non-small cell lung cancer that has spread; the benefit is modest and it is little used.",
    summary: "Necitumumab was approved by the FDA in November 2015 in combination with gemcitabine and cisplatin for first-line metastatic squamous NSCLC, on the SQUIRE trial (1,093 patients) in which adding the antibody produced a small but statistically significant gain in overall survival, while the INSPIRE trial in non-squamous disease was stopped for lack of benefit and excess thromboembolic deaths. The EU authorised Portrazza in 2016 for EGFR-expressing squamous NSCLC. Cardiopulmonary arrest and hypomagnesaemia carry boxed warnings; rash is universal. Immunotherapy-chemotherapy combinations (KEYNOTE-407) have since made it largely obsolete, and it is listed by the NCCN only as an option in selected patients.",
    approvals: [{ region: "US", year: 2015, indication: "First-line metastatic squamous NSCLC with gemcitabine and cisplatin" }, { region: "EU", year: 2016, indication: "EGFR-expressing locally advanced or metastatic squamous NSCLC with gemcitabine and cisplatin" }],
    targets: ["egfr"], cancers: ["nsclc"], companies: ["eli-lilly"], technologies: ["monoclonal-antibody"], related: ["cetuximab", "gemcitabine-cisplatin"], links: label("necitumumab", "necitumumab", [{ label: "EPAR", url: EPAR("portrazza") }]), tags: ["nci-list"] }),
  d({ id: "ofatumumab", name: "Ofatumumab", brand: "Arzerra", aka: ["Kesimpta (multiple sclerosis formulation)"], modality: "Monoclonal antibody (anti-CD20, fully human IgG1)", mechanism: "Binds a distinct small- and large-loop epitope of CD20 close to the membrane, giving potent complement-dependent cytotoxicity as well as antibody-dependent cellular cytotoxicity against B cells.", wikipedia: W("Ofatumumab"),
    tldr: "Ofatumumab (Arzerra) is a fully human anti-CD20 antibody for chronic lymphocytic leukaemia, used with chlorambucil in untreated patients or alone after other drugs have failed; the same molecule is sold as Kesimpta for multiple sclerosis.",
    summary: "Ofatumumab received accelerated FDA approval in October 2009 for CLL refractory to fludarabine and alemtuzumab, then full approvals with chlorambucil in previously untreated CLL where fludarabine is inappropriate (COMPLEMENT-1, 2014: longer progression-free survival than chlorambucil alone), as extended treatment in recurrent or progressive CLL after response (PROLONG, 2016) and with fludarabine and cyclophosphamide in relapsed CLL (COMPLEMENT-2, 2016). The EU granted conditional authorisation in 2010; the marketing authorisation was later withdrawn for commercial reasons and Arzerra is now supplied in many countries through a compassionate programme, while Kesimpta (subcutaneous ofatumumab) is marketed for multiple sclerosis. Hepatitis B reactivation and progressive multifocal leukoencephalopathy carry boxed warnings.",
    approvals: [{ region: "US", year: 2009, indication: "CLL refractory to fludarabine and alemtuzumab (accelerated)" }, { region: "US", year: 2014, indication: "Previously untreated CLL with chlorambucil; later extended treatment and relapsed CLL with fludarabine and cyclophosphamide" }, { region: "EU", year: 2010, indication: "CLL refractory to fludarabine and alemtuzumab (conditional; authorisation since withdrawn)" }],
    targets: ["cd20"], cancers: ["cll"], companies: ["novartis", "genmab"], technologies: ["monoclonal-antibody"], related: ["rituximab", "obinutuzumab"], links: label("ofatumumab", "ofatumumab"), tags: ["nci-list"] }),
  d({ id: "ziv-aflibercept", name: "Ziv-aflibercept", brand: "Zaltrap", aka: ["Aflibercept (oncology formulation)", "VEGF Trap"], modality: "Recombinant fusion protein (VEGF ligand trap)", mechanism: "Fusion of VEGFR1 and VEGFR2 extracellular domains with human IgG1 Fc; binds VEGF-A, VEGF-B and placental growth factor with sub-picomolar affinity, preventing receptor activation and angiogenesis.", wikipedia: W("Aflibercept"),
    tldr: "Ziv-aflibercept (Zaltrap) is a decoy receptor that soaks up the blood-vessel growth signal VEGF. It is added to the FOLFIRI chemotherapy combination for bowel cancer that has spread and progressed after oxaliplatin.",
    summary: "Ziv-aflibercept was approved by the FDA in August 2012 with FOLFIRI for metastatic colorectal cancer resistant to or progressing after an oxaliplatin-containing regimen, on the VELOUR trial (1,226 patients) in which adding the drug modestly improved overall survival and progression-free survival over FOLFIRI plus placebo, including in patients who had received bevacizumab. The EU authorised Zaltrap in 2013. Its role overlaps with bevacizumab continued beyond progression and with ramucirumab (RAISE), and cost has limited uptake. Haemorrhage, gastrointestinal perforation and compromised wound healing carry boxed warnings; hypertension and proteinuria are common. The same molecule is the ophthalmic drug Eylea.",
    approvals: [{ region: "US", year: 2012, indication: "Metastatic colorectal cancer resistant to or progressing after oxaliplatin, with FOLFIRI" }, { region: "EU", year: 2013, indication: "Metastatic colorectal cancer resistant to or progressing after oxaliplatin, with FOLFIRI" }],
    targets: ["vegf"], cancers: ["colorectal"], companies: ["sanofi", "regeneron"], technologies: ["antiangiogenic"], related: ["bevacizumab", "ramucirumab", "folfiri"], links: label("ziv-aflibercept", "ziv-aflibercept", [{ label: "EPAR", url: EPAR("zaltrap") }]), tags: ["nci-list"] }),
  d({ id: "selumetinib", trials: ["nct01933932"], name: "Selumetinib", brand: "Koselugo", modality: "Small-molecule allosteric MEK1/2 inhibitor", mechanism: "Non-ATP-competitive inhibitor of MEK1 and MEK2; in NF1-deficient cells with unrestrained RAS activity it lowers ERK signalling and shrinks plexiform neurofibromas.", wikipedia: W("Selumetinib"),
    tldr: "Selumetinib (Koselugo) is the first medicine for children and adults with neurofibromatosis type 1 whose plexiform neurofibromas, benign but disfiguring and painful nerve tumours, cannot be removed by surgery.",
    summary: "Selumetinib was approved by the FDA in April 2020 for children aged 2 and over with NF1 and symptomatic, inoperable plexiform neurofibromas, on the SPRINT phase 2 stratum 1 trial in which two-thirds of 50 children had a confirmed partial response with improvements in pain and function; approval was extended to adults (KOMET trial) and, with a granule formulation, to children from 1 year in 2025. The EU granted conditional authorisation in 2021. Plexiform neurofibromas are benign tumours, but the drug is an oncology-class MEK inhibitor developed with Merck & Co. Rash, paronychia, diarrhoea, raised creatine kinase, reduced ejection fraction and ocular toxicity are class effects and require monitoring. Mirdametinib (Gomekli, 2025) is the second MEK inhibitor for the same condition.",
    approvals: [{ region: "US", year: 2020, indication: "NF1 with symptomatic, inoperable plexiform neurofibromas, children 2 and over (extended to adults and to age 1 and over in 2025)" }, { region: "EU", year: 2021, indication: "Symptomatic, inoperable plexiform neurofibromas in NF1, children 3 and over (conditional)" }],
    targets: ["mek"], companies: ["astrazeneca", "merck"], technologies: ["kinase-inhibitors"], pathways: ["ras-mapk"], related: ["trametinib"], links: label("selumetinib", "selumetinibsulfate", [{ label: "EPAR", url: EPAR("koselugo") }]), tags: ["nci-list"], notes: ["NF1 plexiform neurofibroma is a benign tumour with no cancer record; not linked to a cancer id."] }),
  d({ id: "siltuximab", name: "Siltuximab", brand: "Sylvant", modality: "Monoclonal antibody (anti-IL-6, chimeric IgG1)", mechanism: "Binds interleukin-6 directly and prevents it engaging soluble and membrane-bound IL-6 receptors, cutting the cytokine drive behind Castleman disease.", wikipedia: W("Siltuximab"),
    tldr: "Siltuximab (Sylvant) is an antibody that neutralises the inflammatory messenger interleukin-6. It is the only approved treatment for multicentric Castleman disease, a rare lymph node disorder, in people without HIV or HHV-8 infection.",
    summary: "Siltuximab was approved by the FDA in April 2014 and by the EU in the same year for multicentric Castleman disease in HIV-negative and HHV-8-negative patients, on a randomised placebo-controlled phase 2 trial of 79 patients in which durable tumour and symptomatic responses occurred only in the siltuximab arm. Castleman disease is a lymphoproliferative disorder rather than a cancer, but it is managed by haematologist-oncologists and the NCI lists siltuximab among cancer drugs. Infusion is every three weeks indefinitely in responders. Because IL-6 blockade suppresses C-reactive protein and fever, infections may be masked; hypertriglyceridaemia and neutropenia occur. Tocilizumab, which blocks the IL-6 receptor, is used in the same disease off label.",
    approvals: [{ region: "US", year: 2014, indication: "Multicentric Castleman disease in HIV-negative and HHV-8-negative patients" }, { region: "EU", year: 2014, indication: "Multicentric Castleman disease in HIV-negative and HHV-8-negative adults" }],
    targets: ["il6"], companies: ["recordati", "johnson-johnson"], technologies: ["monoclonal-antibody"], related: ["tocilizumab"], links: label("siltuximab", "siltuximab", [{ label: "EPAR", url: EPAR("sylvant") }]), tags: ["nci-list"], notes: ["Multicentric Castleman disease is a lymphoproliferative disorder with no cancer record."] }),
  d({ id: "sirolimus-albumin-bound", trials: ["nct05997017", "nct05103358"], name: "Sirolimus protein-bound particles", brand: "Fyarro", aka: ["nab-sirolimus", "ABI-009", "Nanoparticle albumin-bound rapamycin"], modality: "Albumin-bound mTOR inhibitor (intravenous)", mechanism: "Sirolimus bound to albumin nanoparticles; binds FKBP12 and allosterically inhibits mTORC1, the kinase left unrestrained by the TSC1/TSC2 loss that drives PEComa.", wikipedia: W("Sirolimus"),
    tldr: "Fyarro is an infusion of the transplant drug sirolimus packaged in albumin particles. It is the first approved treatment for malignant PEComa, a rare soft-tissue tumour driven by loss of the TSC genes.",
    summary: "Sirolimus protein-bound particles were approved by the FDA in November 2021 for adults with locally advanced unresectable or metastatic malignant perivascular epithelioid cell tumour (PEComa), on the AMPECT single-arm trial in which 39% of 31 patients responded, with responses concentrated in tumours carrying TSC2 inactivation and several lasting over two years. The albumin formulation allows higher intratumoural drug exposure than oral rapalogues. It is being studied in other TSC1/2-altered solid tumours (PRECISION 1). Stomatitis, myelosuppression, hyperglycaemia, hyperlipidaemia and pneumonitis are the mTOR-class effects.",
    approvals: [{ region: "US", year: 2021, indication: "Locally advanced unresectable or metastatic malignant PEComa" }],
    targets: ["mtor"], cancers: ["sarcoma"], technologies: ["kinase-inhibitors"], pathways: ["pi3k-akt-mtor"], related: ["everolimus", "temsirolimus"], links: label("sirolimus protein-bound", "sirolimus-protein-bound-particles"), tags: ["nci-list"] }),
  d({ id: "denosumab", trials: ["nct07028268"], name: "Denosumab", brand: "Xgeva / Prolia", aka: ["Wyost", "Jubbonti", "Osenvelt", "Stoboclo"], modality: "Monoclonal antibody (anti-RANKL, fully human IgG2)", mechanism: "Binds RANK ligand and prevents it activating RANK on osteoclasts and their precursors, suppressing bone resorption and the tumour-bone vicious cycle.", wikipedia: W("Denosumab"),
    tldr: "Denosumab is an injection under the skin that blocks the signal driving bone breakdown. As Xgeva it prevents fractures and other bone complications in people whose cancer has spread to bone or who have myeloma; as Prolia it treats osteoporosis, including bone loss caused by hormone therapy for breast and prostate cancer.",
    summary: "Denosumab (Xgeva, 120 mg monthly) was approved by the FDA in November 2010 for prevention of skeletal-related events in bone metastases from solid tumours, on three phase 3 trials against zoledronic acid in breast cancer, prostate cancer and other solid tumours in which it delayed first skeletal events at least as well as, and in breast and prostate cancer better than, the bisphosphonate. Later Xgeva indications: giant cell tumour of bone (2013), hypercalcaemia of malignancy refractory to bisphosphonates (2014) and multiple myeloma (2018). Prolia (60 mg six-monthly, 2010) treats osteoporosis and bone loss from aromatase inhibitors or androgen deprivation. The EU authorised Prolia in 2010 and Xgeva in 2011; biosimilars (Wyost/Jubbonti, Osenvelt/Stoboclo) reached the market from 2024. Osteonecrosis of the jaw, atypical femoral fractures, hypocalcaemia (boxed warning in advanced kidney disease) and rebound vertebral fractures after stopping are the key risks; unlike bisphosphonates it needs no renal dose adjustment.",
    approvals: [{ region: "US", year: 2010, indication: "Prevention of skeletal-related events in bone metastases from solid tumours (Xgeva); postmenopausal osteoporosis and treatment-induced bone loss (Prolia)" }, { region: "US", year: 2013, indication: "Giant cell tumour of bone; hypercalcaemia of malignancy (2014); multiple myeloma (2018)" }, { region: "EU", year: 2011, indication: "Prevention of skeletal-related events in bone metastases and, later, multiple myeloma; giant cell tumour of bone (Xgeva)" }],
    targets: ["rankl"], cancers: ["breast-hr-positive", "prostate", "multiple-myeloma", "nsclc", "osteosarcoma"], companies: ["amgen"], technologies: ["bone-modifying-agents", "monoclonal-antibody"], related: ["zoledronic-acid"], links: label("denosumab", "denosumab", [{ label: "EPAR (Xgeva)", url: EPAR("xgeva") }]), tags: ["nci-list", "supportive"], terms: ["bone-metastases"] }),
  d({ id: "zoledronic-acid", name: "Zoledronic acid", brand: "Zometa", aka: ["Reclast / Aclasta (osteoporosis formulation)", "Zoledronate"], modality: "Nitrogen-containing bisphosphonate (intravenous)", mechanism: "Binds bone mineral and inhibits farnesyl pyrophosphate synthase in osteoclasts, blocking prenylation of signalling proteins and inducing osteoclast apoptosis; reduces bone resorption and calcium release.", wikipedia: W("Zoledronic_acid"),
    tldr: "Zoledronic acid (Zometa) is a fifteen-minute infusion given every few weeks or months to strengthen bone and prevent fractures, spinal cord compression and the need for radiotherapy in people with myeloma or cancer that has spread to bone; it also treats dangerously high calcium caused by cancer.",
    summary: "Zoledronic acid was approved by the FDA in August 2001 for hypercalcaemia of malignancy (two randomised trials against pamidronate showed faster and more complete normalisation of calcium) and in 2002 for multiple myeloma and bone metastases from solid tumours in conjunction with antineoplastic therapy, on trials in breast cancer, prostate cancer, lung and other solid tumours that reduced skeletal-related events. The EU authorised Zometa in 2001. Every-12-week dosing was shown non-inferior to monthly (CALGB 70604), and adjuvant zoledronic acid reduces recurrence and death in postmenopausal early breast cancer (EBCTCG meta-analysis), an off-label but guideline-endorsed use. Osteonecrosis of the jaw, renal impairment (dose adjustment and creatinine monitoring) and acute-phase reactions after the first dose are the main risks. Denosumab is the alternative when renal function is poor.",
    approvals: [{ region: "US", year: 2001, indication: "Hypercalcaemia of malignancy" }, { region: "US", year: 2002, indication: "Multiple myeloma and bone metastases from solid tumours, with antineoplastic therapy" }, { region: "EU", year: 2001, indication: "Prevention of skeletal-related events in advanced malignancies involving bone; tumour-induced hypercalcaemia" }],
    cancers: ["multiple-myeloma", "breast-hr-positive", "prostate", "nsclc", "rcc"], companies: ["novartis"], technologies: ["bone-modifying-agents"], related: ["denosumab", "pamidronate"], links: label("zoledronic acid", "zoledronicacid", [{ label: "EPAR", url: EPAR("zometa") }]), tags: ["nci-list", "generic", "supportive"], terms: ["bone-metastases"] }),
  d({ id: "pamidronate", name: "Pamidronate", brand: "Aredia (historic)", modality: "Nitrogen-containing bisphosphonate (intravenous)", mechanism: "Adsorbs to hydroxyapatite and inhibits osteoclast-mediated bone resorption, lowering serum calcium and reducing osteolytic lesion progression.", wikipedia: W("Pamidronic_acid"),
    tldr: "Pamidronate (Aredia) is a bisphosphonate infusion approved in 1991 for dangerously high blood calcium in cancer and later for bone damage from myeloma and breast cancer, where it roughly halved skeletal complications. Its two-hour infusion, against fifteen minutes for zoledronic acid, pushed most centres to switch, though it is cheaper and may cause less jaw osteonecrosis.",
    summary: "Pamidronate disodium was approved in October 1991 for moderate or severe hypercalcaemia of malignancy with or without bone metastases and later for osteolytic bone metastases of breast cancer and osteolytic lesions of multiple myeloma in conjunction with standard antineoplastic therapy, on placebo-controlled trials (Hortobagyi 1996, Berenson 1996) that roughly halved skeletal complications. The two-hour infusion, compared with fifteen minutes for zoledronic acid, and the pivotal head-to-head hypercalcaemia trials led most centres to switch, although pamidronate remains a lower-cost generic option and is preferred by some in myeloma because of a lower rate of osteonecrosis of the jaw in observational series. Renal toxicity with rapid infusion, acute-phase reactions and jaw osteonecrosis are the key risks.",
    approvals: [{ region: "US", year: 1991, indication: "Hypercalcaemia of malignancy" }, { region: "US", year: 1995, indication: "Osteolytic bone metastases of breast cancer and osteolytic lesions of multiple myeloma, with antineoplastic therapy" }],
    cancers: ["multiple-myeloma", "breast-hr-positive"], companies: ["novartis"], technologies: ["bone-modifying-agents"], related: ["zoledronic-acid", "denosumab"], links: label("pamidronate", "pamidronatedisodium"), tags: ["nci-list", "generic", "supportive"] }),
  d({ id: "tocilizumab", trials: ["nct07589634", "nct04077723", "nct05583617", "nct05535244", "nct04246086", "nct05207670", "nct03075696", "nct03671018", "nct04524871", "nct06084936", "nct03533283", "nct04980222"], name: "Tocilizumab", brand: "Actemra", aka: ["RoActemra", "Tofidence", "Tyenne"], modality: "Monoclonal antibody (anti-IL-6 receptor, humanised IgG1)", mechanism: "Binds soluble and membrane-bound IL-6 receptors and blocks IL-6 signalling, the central mediator of cytokine release syndrome after T-cell-redirecting therapy.", wikipedia: W("Tocilizumab"),
    tldr: "Tocilizumab (Actemra) is a rheumatoid arthritis antibody that has become the rescue drug for cytokine release syndrome, the fever and blood-pressure crash that CAR-T cells and bispecific antibodies can trigger. Every CAR-T centre must have it on hand.",
    summary: "Tocilizumab was approved by the FDA in 2010 for rheumatoid arthritis and in August 2017, on the same day as the first CAR-T approval (tisagenlecleucel), for severe or life-threatening CAR-T-cell-induced cytokine release syndrome in patients aged 2 and over, on a retrospective analysis of pooled CAR-T trials in which about two-thirds of patients had CRS resolve within 14 days of one or two doses. The CAR-T REMS programmes require two doses to be available on site for every patient, and it is used with the same logic for CRS from bispecific T-cell engagers, though not on label. Because it does not cross the blood-brain barrier it does not treat neurotoxicity (ICANS), for which corticosteroids are used. The EU authorised RoActemra in 2009; biosimilars (Tofidence, Tyenne) followed in 2023 to 2024. Serious infection carries a boxed warning in chronic use.",
    approvals: [{ region: "US", year: 2010, indication: "Rheumatoid arthritis (first approval)" }, { region: "US", year: 2017, indication: "Severe or life-threatening CAR-T-cell-induced cytokine release syndrome, age 2 and over" }],
    targets: ["il6"], companies: ["roche-genentech"], technologies: ["car-t", "t-cell-engager", "monoclonal-antibody"], related: ["siltuximab", "tisagenlecleucel"], links: label("tocilizumab", "tocilizumab"), tags: ["nci-list", "supportive"] }),
];

// =====================================================================================
// Batch 3: supportive care on the NCI list: antiemetics, cytoprotectants, growth factors, rescue agents, vaccines
