const batch3: DrugInput[] = [
  d({ id: "amifostine", trials: ["nct07157033"], name: "Amifostine", brand: "Ethyol", aka: ["WR-2721"], modality: "Cytoprotective thiol prodrug", mechanism: "Dephosphorylated by alkaline phosphatase, which is more abundant in normal tissue, to the free thiol WR-1065 that scavenges reactive oxygen species and binds cisplatin metabolites, protecting kidney and salivary tissue.", wikipedia: W("Amifostine"),
    tldr: "Amifostine (Ethyol) is an infusion given just before chemotherapy or radiotherapy to shield the kidneys from cisplatin and the salivary glands from radiation, reducing dry mouth after head and neck treatment.",
    summary: "Amifostine was approved in December 1995 to reduce cumulative renal toxicity from repeated cisplatin in advanced ovarian cancer and in 1999 to reduce moderate to severe xerostomia during post-operative radiotherapy for head and neck cancer when the field includes much of the parotid glands, on randomised trials in each setting. Concern that a radioprotector might also shield tumours, together with nausea, hypotension during infusion and skin reactions, has confined it to selected patients, and intensity-modulated radiotherapy has largely replaced it for salivary sparing. Guidelines (ASCO, MASCC) list it as an option rather than a standard.",
    approvals: [{ region: "US", year: 1995, indication: "Reduction of cumulative cisplatin renal toxicity in advanced ovarian cancer" }, { region: "US", year: 1999, indication: "Reduction of moderate to severe xerostomia from post-operative radiotherapy for head and neck cancer" }],
    cancers: ["ovarian", "head-and-neck"], technologies: ["imrt-igrt"], links: label("amifostine", "amifostine"), tags: ["nci-list", "supportive"] }),
  d({ id: "aprepitant", trials: ["nct06904235"], name: "Aprepitant (and fosaprepitant)", brand: "Emend / Cinvanti", aka: ["Fosaprepitant", "Ivemend", "Emend IV", "Aponvie"], modality: "Neurokinin-1 receptor antagonist (antiemetic)", mechanism: "Selective high-affinity antagonist of substance P at NK1 receptors in the brainstem vomiting centre; fosaprepitant is an intravenous prodrug converted to aprepitant within minutes.", wikipedia: W("Aprepitant"),
    tldr: "Aprepitant (Emend) was the first of a new class of anti-sickness drugs. Taken with a 5-HT3 blocker and dexamethasone, it prevents the delayed nausea and vomiting that follow strongly emetogenic chemotherapy such as cisplatin.",
    summary: "Aprepitant capsules were approved by the FDA in March 2003 for prevention of acute and delayed nausea and vomiting with highly emetogenic chemotherapy, extended to moderately emetogenic regimens in 2005, with the intravenous prodrug fosaprepitant (Emend for injection) approved in 2008 and a paediatric oral suspension from 6 months of age in 2015; Cinvanti (2017) is an intravenous aprepitant emulsion. In the pivotal cisplatin trials, adding aprepitant to ondansetron and dexamethasone raised complete response rates by roughly 20 percentage points, establishing triple therapy as the standard that every guideline (ASCO, MASCC/ESMO, NCCN) now recommends for highly emetogenic chemotherapy. The EU authorised Emend in 2003 and Ivemend in 2008. It is a moderate CYP3A4 inhibitor, so dexamethasone doses are halved and interactions with some chemotherapy and warfarin need attention.",
    approvals: [{ region: "US", year: 2003, indication: "Prevention of acute and delayed nausea and vomiting with highly emetogenic chemotherapy (moderately emetogenic added 2005; paediatric suspension 2015)" }, { region: "US", year: 2008, indication: "Fosaprepitant intravenous prodrug for the same indications" }, { region: "EU", year: 2003, indication: "Prevention of chemotherapy-induced nausea and vomiting (Emend); Ivemend 2008" }],
    companies: ["merck", "heron-therapeutics"], technologies: ["antiemetic-therapy"], related: ["ondansetron", "palonosetron", "dexamethasone"], links: label("aprepitant", "aprepitant", [{ label: "EPAR (Emend)", url: EPAR("emend") }]), tags: ["nci-list", "supportive"] }),
  d({ id: "granisetron", name: "Granisetron", brand: "Kytril (historic) / Sancuso / Sustol", aka: ["Granisetron hydrochloride", "Granisetron transdermal system", "Granisetron extended-release injection"], modality: "5-HT3 receptor antagonist (antiemetic)", mechanism: "Selective serotonin 5-HT3 receptor antagonist acting on vagal afferents in the gut and the chemoreceptor trigger zone.", wikipedia: W("Granisetron"),
    tldr: "Granisetron is an anti-sickness medicine for chemotherapy given as a tablet, an injection, a week-long skin patch (Sancuso) or a slow-release injection that lasts several days (Sustol).",
    summary: "Granisetron (Kytril) was approved in December 1993 for prevention of nausea and vomiting from emetogenic chemotherapy, with tablets and a radiotherapy indication following; oral and intravenous granisetron are now generic. Two formulations extended its reach: the Sancuso transdermal patch (2008) applied 24 to 48 hours before chemotherapy and worn for up to seven days for regimens of up to five consecutive days, and Sustol (2016), a polymer-based extended-release subcutaneous injection that maintains levels for at least five days and is approved with other antiemetics for acute and delayed nausea and vomiting after moderately emetogenic or anthracycline-cyclophosphamide chemotherapy. The EU authorised Sancuso in 2012. Headache and constipation are the class effects; QT prolongation is less than with dolasetron.",
    approvals: [{ region: "US", year: 1993, indication: "Prevention of nausea and vomiting from emetogenic chemotherapy (Kytril; radiotherapy later)" }, { region: "US", year: 2008, indication: "Transdermal system for chemotherapy of up to five consecutive days (Sancuso)" }, { region: "US", year: 2016, indication: "Extended-release injection for acute and delayed nausea and vomiting with moderately emetogenic or anthracycline-cyclophosphamide chemotherapy (Sustol)" }, { region: "EU", year: 2012, indication: "Transdermal granisetron for moderately or highly emetogenic chemotherapy (Sancuso)" }],
    companies: ["heron-therapeutics"], technologies: ["antiemetic-therapy"], related: ["ondansetron", "palonosetron"], links: label("granisetron", "granisetron", [{ label: "NCI page (granisetron hydrochloride)", url: NCI("granisetronhydrochloride") }, { label: "EPAR (Sancuso)", url: EPAR("sancuso") }]), tags: ["nci-list", "supportive", "generic"] }),
  d({ id: "ondansetron", trials: ["nct06904235"], name: "Ondansetron", brand: "Zofran", aka: ["Zuplenz (oral film)"], modality: "5-HT3 receptor antagonist (antiemetic)", mechanism: "Selective antagonist of serotonin 5-HT3 receptors on vagal afferent nerves and in the chemoreceptor trigger zone; blocks the serotonin surge released from enterochromaffin cells by chemotherapy and radiation.", wikipedia: W("Ondansetron"),
    tldr: "Ondansetron (Zofran) was the drug that made cisplatin-type chemotherapy bearable. It blocks the serotonin signal that triggers vomiting and is now a cheap generic tablet, dissolving wafer or injection used across cancer care.",
    summary: "Ondansetron was approved in January 1991 for prevention of nausea and vomiting from highly emetogenic chemotherapy including cisplatin, with moderately emetogenic chemotherapy, radiotherapy (total body irradiation and abdominal fields) and post-operative nausea added later, and oral, orally disintegrating, film and injectable forms available. Its introduction, the first selective 5-HT3 antagonist, transformed supportive care and it remains the backbone of antiemetic prophylaxis worldwide and on the WHO essential medicines list. QT prolongation led the FDA to withdraw the 32 mg single intravenous dose in 2012; headache and constipation are common and serotonin syndrome is a rare interaction. Palonosetron and granisetron are the longer-acting alternatives.",
    approvals: [{ region: "US", year: 1991, indication: "Prevention of nausea and vomiting from highly emetogenic chemotherapy; later moderately emetogenic chemotherapy, radiotherapy and post-operative nausea" }],
    technologies: ["antiemetic-therapy"], related: ["granisetron", "palonosetron", "aprepitant"], links: label("ondansetron", "ondansetronhydrochloride"), tags: ["nci-list", "supportive", "generic"] }),
  d({ id: "palonosetron", trials: ["nct06904235"], name: "Palonosetron", brand: "Aloxi", aka: ["Posfrea"], modality: "Second-generation 5-HT3 receptor antagonist (antiemetic)", mechanism: "High-affinity 5-HT3 antagonist with a 40-hour half-life that also triggers receptor internalisation and inhibits crosstalk with NK1 signalling, which is thought to explain its effect on delayed emesis.", wikipedia: W("Palonosetron"),
    tldr: "Palonosetron (Aloxi) is a long-acting anti-sickness injection given once before chemotherapy; a single dose covers both the first day and the delayed nausea that follows.",
    summary: "Palonosetron was approved by the FDA in July 2003 for prevention of acute and delayed nausea and vomiting with moderately emetogenic chemotherapy and acute nausea and vomiting with highly emetogenic chemotherapy, on randomised trials against ondansetron and dolasetron in which a single 0.25 mg dose was non-inferior in the acute phase and superior over five days; post-operative nausea (2008) and a paediatric indication from one month of age (2014) followed. The EU authorised Aloxi in 2005. It is the 5-HT3 partner in the Akynzeo fixed combination with netupitant and is preferred by MASCC/ESMO guidelines for moderately emetogenic regimens when an NK1 antagonist is not used. Headache and constipation are the main adverse effects, with less QT effect than first-generation agents.",
    approvals: [{ region: "US", year: 2003, indication: "Acute and delayed nausea and vomiting with moderately emetogenic chemotherapy; acute with highly emetogenic chemotherapy (paediatric from 1 month added 2014)" }, { region: "EU", year: 2005, indication: "Prevention of chemotherapy-induced nausea and vomiting (Aloxi)" }],
    companies: ["helsinn", "eisai"], technologies: ["antiemetic-therapy"], related: ["netupitant-palonosetron", "ondansetron"], links: label("palonosetron", "palonosetronhydrochloride", [{ label: "EPAR", url: EPAR("aloxi") }]), tags: ["nci-list", "supportive"] }),
  d({ id: "netupitant-palonosetron", name: "Netupitant and palonosetron", brand: "Akynzeo", aka: ["NEPA", "Fosnetupitant and palonosetron (intravenous)"], modality: "Fixed combination NK1 antagonist plus 5-HT3 antagonist (antiemetic)", mechanism: "Netupitant, a long-acting substance P/NK1 receptor antagonist, blocks delayed emesis while palonosetron, a 5-HT3 antagonist, covers the acute phase; a single capsule or infusion with dexamethasone.", wikipedia: W("Netupitant/palonosetron"),
    tldr: "Akynzeo combines two anti-sickness drugs in one capsule or infusion taken once before chemotherapy, so a single dose plus dexamethasone protects against both immediate and delayed vomiting.",
    summary: "Netupitant/palonosetron was approved by the FDA in October 2014 for prevention of acute and delayed nausea and vomiting with initial and repeat courses of chemotherapy including highly emetogenic regimens, in combination with dexamethasone, on phase 3 trials against palonosetron alone in cisplatin and anthracycline-cyclophosphamide regimens in which complete response over five days was higher, a statistically significant difference; the intravenous fosnetupitant/palonosetron formulation followed in 2018. The EU authorised Akynzeo in 2015. It simplifies the guideline-recommended triple regimen to one antiemetic product plus a steroid. Headache, asthenia and constipation are the main adverse effects; netupitant is a moderate CYP3A4 inhibitor.",
    approvals: [{ region: "US", year: 2014, indication: "Acute and delayed chemotherapy-induced nausea and vomiting including highly emetogenic regimens, with dexamethasone (intravenous form 2018)" }, { region: "EU", year: 2015, indication: "Acute and delayed nausea and vomiting with highly and moderately emetogenic chemotherapy (Akynzeo)" }],
    companies: ["helsinn"], technologies: ["antiemetic-therapy"], related: ["palonosetron", "aprepitant"], links: label("netupitant", "netupitant-palonosetronhydrochloride", [{ label: "EPAR", url: EPAR("akynzeo") }]), tags: ["nci-list", "supportive"] }),
  d({ id: "rolapitant", name: "Rolapitant", brand: "Varubi", aka: ["Varuby"], modality: "Neurokinin-1 receptor antagonist (antiemetic)", mechanism: "Selective, competitive substance P/NK1 receptor antagonist with a half-life of about seven days, so one oral dose covers the delayed phase; unlike aprepitant it does not inhibit CYP3A4.", wikipedia: W("Rolapitant"),
    tldr: "Rolapitant (Varubi) is a long-lasting anti-sickness tablet taken once before chemotherapy, alongside a 5-HT3 blocker and dexamethasone, to prevent nausea and vomiting in the days after treatment.",
    summary: "Rolapitant was approved by the FDA in September 2015 in combination with other antiemetics for prevention of delayed nausea and vomiting with initial and repeat courses of emetogenic chemotherapy including highly emetogenic regimens, on three phase 3 trials (two in cisplatin-based and one in moderately emetogenic chemotherapy) in which complete response in the delayed phase was higher than with granisetron and dexamethasone alone, a statistically significant difference. An intravenous emulsion approved in 2017 was withdrawn after anaphylaxis reports. Its long half-life and lack of CYP3A4 inhibition avoid the dexamethasone dose adjustment required with aprepitant, but it inhibits CYP2D6 and BCRP, so thioridazine is contraindicated and irinotecan and methotrexate exposure may rise. Marketed in the US by TerSera.",
    approvals: [{ region: "US", year: 2015, indication: "Prevention of delayed nausea and vomiting with emetogenic chemotherapy, in combination with other antiemetics" }],
    companies: ["tersera-therapeutics"], technologies: ["antiemetic-therapy"], related: ["aprepitant", "netupitant-palonosetron"], links: label("rolapitant", "rolapitanthydrochloride"), tags: ["nci-list", "supportive"] }),
  d({ id: "dexrazoxane", name: "Dexrazoxane", brand: "Zinecard / Totect", aka: ["Cardioxane", "Savene"], modality: "Cardioprotectant and extravasation antidote (bisdioxopiperazine)", mechanism: "Cyclic EDTA derivative hydrolysed intracellularly to a metal chelator that removes iron from anthracycline-iron complexes, limiting free-radical cardiac injury; also a catalytic topoisomerase II inhibitor, which underlies its action against extravasation injury.", wikipedia: W("Dexrazoxane"),
    tldr: "Dexrazoxane protects the heart from the cumulative damage of doxorubicin in women with metastatic breast cancer who need to keep receiving it, and, as Totect, limits tissue destruction when an anthracycline leaks out of a vein.",
    summary: "Dexrazoxane (Zinecard) was approved in May 1995 to reduce the incidence and severity of doxorubicin cardiomyopathy in women with metastatic breast cancer who have received a cumulative 300 mg/m2 and will continue doxorubicin, on randomised trials that markedly reduced cardiac events; it is not used from the start of treatment because of an early signal of reduced response, later not confirmed. Totect was approved in 2007 for anthracycline extravasation, given within six hours on three consecutive days, on two single-arm European studies in which surgery was avoided in the great majority. Dexrazoxane is also used in paediatric leukaemia and lymphoma protocols to protect against late cardiotoxicity, an area where long-term Children's Oncology Group follow-up has been reassuring about secondary malignancy. Myelosuppression adds to that of chemotherapy.",
    approvals: [{ region: "US", year: 1995, indication: "Reduction of doxorubicin cardiomyopathy in women with metastatic breast cancer after 300 mg/m2 cumulative dose (Zinecard)" }, { region: "US", year: 2007, indication: "Anthracycline extravasation (Totect)" }],
    cancers: ["breast-hr-positive", "all-leukemia"], technologies: ["cardio-oncology"], related: ["doxorubicin"], links: label("dexrazoxane", "dexrazoxanehydrochloride"), tags: ["nci-list", "supportive"] }),
  d({ id: "mesna", trials: ["nct07255664", "nct06119685"], name: "Mesna", brand: "Mesnex", aka: ["Uromitexan", "Sodium 2-mercaptoethanesulfonate"], modality: "Uroprotective thiol", mechanism: "Free thiol excreted in urine that binds and detoxifies acrolein and 4-hydroxy-ifosfamide, the urotoxic metabolites of ifosfamide and cyclophosphamide, in the bladder.", wikipedia: W("Mesna"),
    tldr: "Mesna is given with the chemotherapy ifosfamide (and high-dose cyclophosphamide) to stop its breakdown products from burning the bladder lining and causing bleeding.",
    summary: "Mesna was approved in December 1988 as a prophylactic agent to reduce the incidence of ifosfamide-induced haemorrhagic cystitis, with oral tablets approved in 2002 allowing intravenous-then-oral schedules; it is given with every ifosfamide dose (sarcoma, germ cell, lymphoma regimens such as ICE and VeIP) and with high-dose cyclophosphamide in transplant conditioning. The label notes it does not prevent haematuria from other causes such as thrombocytopenia. Hypersensitivity reactions, including rare severe skin reactions, and false-positive urine ketone tests are the practical issues; nausea and headache are common.",
    approvals: [{ region: "US", year: 1988, indication: "Prophylaxis of ifosfamide-induced haemorrhagic cystitis (oral tablets 2002)" }],
    companies: ["baxter"], related: ["ifosfamide", "cyclophosphamide"], links: label("mesna", "mesna"), tags: ["nci-list", "supportive", "generic"] }),
  d({ id: "glucarpidase", name: "Glucarpidase", brand: "Voraxaze", aka: ["Carboxypeptidase G2"], modality: "Recombinant bacterial enzyme (rescue agent)", mechanism: "Carboxypeptidase G2 from Pseudomonas that cleaves the terminal glutamate from methotrexate, converting it within minutes to inactive DAMPA and glutamate, independent of renal function.", wikipedia: W("Glucarpidase"),
    tldr: "Glucarpidase (Voraxaze) is a single emergency injection that chops up methotrexate in the blood when a patient's kidneys have failed to clear a high dose, preventing potentially fatal toxicity.",
    summary: "Glucarpidase was approved by the FDA in January 2012 to reduce toxic plasma methotrexate concentrations (above 1 micromole per litre) in adults and children with delayed methotrexate clearance due to impaired renal function, on pooled single-arm studies in which a single 50 units/kg dose lowered methotrexate by more than 95% within 15 minutes in almost all patients. It does not replace leucovorin, which must continue (given at least two hours apart because glucarpidase also cleaves leucovorin), and it is not for patients with expected clearance. In the EU it is available through named-patient supply rather than a central authorisation. Marketed by BTG, now SERB.",
    approvals: [{ region: "US", year: 2012, indication: "Toxic plasma methotrexate concentrations with delayed clearance due to impaired renal function" }],
    companies: ["serb-pharmaceuticals"], related: ["methotrexate"], links: label("glucarpidase", "glucarpidase"), tags: ["nci-list", "supportive"] }),
  d({ id: "uridine-triacetate", name: "Uridine triacetate", brand: "Vistogard", aka: ["Xuriden (hereditary orotic aciduria formulation)"], modality: "Pyrimidine analogue antidote (oral)", mechanism: "Acetylated prodrug of uridine; delivered uridine is converted to uridine triphosphate, which competes with fluorouracil metabolites for incorporation into RNA and restores normal pyrimidine pools.", wikipedia: W("Uridine_triacetate"),
    tldr: "Uridine triacetate (Vistogard) is an oral antidote for fluorouracil or capecitabine overdose, or for dangerously early severe toxicity from these drugs, and must be started within four days of the chemotherapy.",
    summary: "Uridine triacetate was approved by the FDA in December 2015 for emergency treatment of adults and children after a fluorouracil or capecitabine overdose regardless of symptoms, or with early-onset severe or life-threatening cardiac, neurological, gastrointestinal or haematological toxicity within 96 hours of the end of administration, on two open-label studies in which 96% of 135 treated patients survived compared with historical mortality of around 84% after overdose. The 96-hour window means it must be given before toxicity is fully manifest; it is not indicated for routine expected toxicity. Patients with DPD deficiency are a key group. Diarrhoea, nausea and vomiting are the main adverse effects. Developed by Wellstat and marketed by BTG, now SERB.",
    approvals: [{ region: "US", year: 2015, indication: "Emergency treatment after fluorouracil or capecitabine overdose or early-onset severe toxicity within 96 hours" }],
    companies: ["serb-pharmaceuticals"], related: ["fluorouracil", "capecitabine"], links: label("uridine triacetate", "uridinetriacetate"), tags: ["nci-list", "supportive"] }),
  d({ id: "palifermin", name: "Palifermin", brand: "Kepivance", aka: ["Recombinant keratinocyte growth factor", "rHuKGF"], modality: "Recombinant human keratinocyte growth factor", mechanism: "Truncated recombinant KGF (FGF7) that binds the KGF receptor (FGFR2b) on epithelial cells of the mouth and gut, stimulating proliferation, differentiation and cytoprotection of the mucosa.", wikipedia: W("Palifermin"),
    tldr: "Palifermin (Kepivance) is a growth factor injected for three days before and after high-dose chemotherapy and stem cell rescue to reduce the severe mouth ulcers (mucositis) that this treatment causes in people with blood cancers.",
    summary: "Palifermin was approved by the FDA in December 2004 to decrease the incidence and duration of severe oral mucositis in patients with haematological malignancies receiving myelotoxic therapy with autologous stem cell support, when the regimen is expected to cause WHO grade 3 or worse mucositis in most patients; in the pivotal randomised trial of 212 patients receiving total body irradiation-based conditioning, grade 3 to 4 mucositis fell from 98% to 63% and its duration from 9 to 3 days. The EU authorised Kepivance in 2005. Its safety in non-haematological malignancies is not established because KGF receptors are present on many epithelial tumours, and it is not given within 24 hours of chemotherapy. Rash, tongue thickening and taste change are the usual effects. Marketed by Sobi.",
    approvals: [{ region: "US", year: 2004, indication: "Reduction of severe oral mucositis in haematological malignancies with myelotoxic therapy and autologous stem cell support" }, { region: "EU", year: 2005, indication: "Same (Kepivance)" }],
    cancers: ["multiple-myeloma", "dlbcl", "hodgkin-lymphoma"], companies: ["sobi"], technologies: ["autologous-stem-cell-transplant"], links: label("palifermin", "palifermin", [{ label: "EPAR", url: EPAR("kepivance") }]), tags: ["nci-list", "supportive"] }),
  d({ id: "rasburicase", name: "Rasburicase", brand: "Elitek", aka: ["Fasturtec", "Recombinant urate oxidase"], modality: "Recombinant enzyme (urate oxidase)", mechanism: "Recombinant Aspergillus urate oxidase that converts uric acid to allantoin, which is five to ten times more soluble and readily excreted, lowering plasma uric acid within hours.", wikipedia: W("Rasburicase"),
    tldr: "Rasburicase (Elitek) is an enzyme infusion that rapidly dissolves the uric acid released when large numbers of leukaemia or lymphoma cells die at the start of treatment, protecting the kidneys from tumour lysis syndrome.",
    summary: "Rasburicase was approved by the FDA in July 2002 for initial management of plasma uric acid in children (adults added 2009) with leukaemia, lymphoma or solid tumours receiving therapy expected to cause tumour lysis, on randomised trials against allopurinol in which uric acid normalised within four hours in almost all patients; the EU authorised Fasturtec in 2001. It is standard for high-risk tumour lysis syndrome (Burkitt lymphoma, high-count ALL and AML, venetoclax ramp-up in CLL with bulky disease), often as a single dose rather than the labelled five days. Haemolysis and methaemoglobinaemia in G6PD deficiency, anaphylaxis and interference with uric acid assays (samples must be chilled) carry boxed warnings.",
    approvals: [{ region: "US", year: 2002, indication: "Initial management of plasma uric acid in paediatric patients with leukaemia, lymphoma or solid tumours at risk of tumour lysis (adults added 2009)" }, { region: "EU", year: 2001, indication: "Treatment and prophylaxis of acute hyperuricaemia in haematological malignancy with high tumour burden (Fasturtec)" }],
    cancers: ["all-leukemia", "aml", "dlbcl", "cll"], companies: ["sanofi"], links: label("rasburicase", "rasburicase", [{ label: "EPAR (Fasturtec)", url: EPAR("fasturtec") }]), tags: ["nci-list", "supportive"] }),
  d({ id: "plerixafor", name: "Plerixafor", brand: "Mozobil", aka: ["AMD3100"], modality: "Small-molecule CXCR4 antagonist (stem cell mobiliser)", mechanism: "Bicyclam that reversibly blocks CXCR4 binding of stromal-derived factor-1 (CXCL12), releasing haematopoietic stem cells from bone marrow niches into the blood within hours.", wikipedia: W("Plerixafor"),
    tldr: "Plerixafor (Mozobil) is an injection given with G-CSF to flush stem cells out of the bone marrow into the blood so that enough can be collected for an autologous transplant in myeloma or lymphoma.",
    summary: "Plerixafor was approved by the FDA in December 2008 in combination with filgrastim to mobilise haematopoietic stem cells for collection and autologous transplantation in non-Hodgkin lymphoma and multiple myeloma, on two placebo-controlled phase 3 trials in which the proportion of patients reaching the target cell dose in few apheresis sessions roughly doubled; the EU authorised Mozobil in 2009 and a paediatric extension followed. It is used routinely for poor mobilisers and increasingly pre-emptively, and the same CXCR4 blockade underlies its investigation to mobilise stem cells for gene therapy and to sensitise leukaemia to chemotherapy. Motixafortide (Aphexda, 2023) is a longer-acting CXCR4 antagonist for the same purpose. Diarrhoea, nausea and injection-site reactions are common.",
    approvals: [{ region: "US", year: 2008, indication: "Stem cell mobilisation with filgrastim for autologous transplantation in NHL and multiple myeloma" }, { region: "EU", year: 2009, indication: "Stem cell mobilisation with G-CSF in lymphoma and multiple myeloma with poor mobilisation (Mozobil)" }],
    targets: ["cxcr4"], cancers: ["multiple-myeloma", "dlbcl", "follicular-lymphoma", "mantle-cell-lymphoma"], companies: ["sanofi"], technologies: ["autologous-stem-cell-transplant", "apheresis-starting-material"], related: ["filgrastim"], links: label("plerixafor", "plerixafor", [{ label: "EPAR", url: EPAR("mozobil") }]), tags: ["nci-list", "supportive"] }),
  d({ id: "filgrastim", trials: ["nct06212752", "nct06514508", "nct03246529", "nct05722015"], name: "Filgrastim (G-CSF)", brand: "Neupogen", aka: ["Zarxio (filgrastim-sndz)", "Nivestym (filgrastim-aafi)", "Releuko (filgrastim-ayow)", "Granix (tbo-filgrastim)", "Nypozi", "Zarzio", "Tevagrastim", "Ratiograstim", "Accofil", "Grastofil"], modality: "Recombinant granulocyte colony-stimulating factor", mechanism: "Recombinant methionyl human G-CSF that binds the G-CSF receptor on myeloid progenitors, driving neutrophil proliferation, differentiation and release from marrow.", wikipedia: W("Filgrastim"),
    tldr: "Filgrastim (Neupogen and its biosimilars) is a daily injection that speeds the recovery of infection-fighting white cells after chemotherapy, lets doctors give chemotherapy on schedule and mobilises stem cells for transplant.",
    summary: "Filgrastim was approved by the FDA in February 1991 to reduce the incidence of infection from febrile neutropenia in non-myeloid malignancies receiving myelosuppressive chemotherapy, and later for AML induction, bone marrow transplantation, peripheral blood progenitor cell mobilisation, severe chronic neutropenia and acute radiation syndrome. It was the first Amgen blockbuster and the model for supportive-care biologics; the first US biosimilar of any kind was filgrastim-sndz (Zarxio, 2015), and the EU authorised the first filgrastim biosimilars in 2008. Guidelines recommend primary prophylaxis when the febrile neutropenia risk of a regimen exceeds about 20%. Bone pain is the main adverse effect; splenic rupture, acute respiratory distress syndrome and sickle cell crises are rare but serious. Pegfilgrastim gives a once-per-cycle alternative.",
    approvals: [{ region: "US", year: 1991, indication: "Reduction of febrile neutropenia in non-myeloid malignancies on myelosuppressive chemotherapy; later AML induction, transplantation, stem cell mobilisation, severe chronic neutropenia" }, { region: "US", year: 2015, indication: "First US biosimilar (Zarxio, filgrastim-sndz); further biosimilars 2018 onwards" }, { region: "EU", year: 2008, indication: "First biosimilar filgrastims (Tevagrastim, Ratiograstim, Biograstim); Zarzio 2009" }],
    companies: ["amgen", "sandoz", "teva"], technologies: ["g-csf-growth-factors"], related: ["pegfilgrastim", "plerixafor"], links: label("filgrastim", "filgrastim", [{ label: "EPAR (Zarzio)", url: EPAR("zarzio") }]), tags: ["nci-list", "supportive"] }),
  d({ id: "pegfilgrastim", trials: ["nct06690775"], name: "Pegfilgrastim", brand: "Neulasta", aka: ["Fulphila (pegfilgrastim-jmdb)", "Udenyca (pegfilgrastim-cbqv)", "Ziextenzo (pegfilgrastim-bmez)", "Nyvepria (pegfilgrastim-apgf)", "Fylnetra", "Stimufend", "Undencyca", "Neulasta Onpro on-body injector"], modality: "Pegylated recombinant granulocyte colony-stimulating factor", mechanism: "Filgrastim with a 20 kDa polyethylene glycol chain that abolishes renal clearance so that elimination depends on neutrophil-mediated uptake; levels fall as neutrophils recover, giving self-regulating once-per-cycle dosing.", wikipedia: W("Pegfilgrastim"),
    tldr: "Pegfilgrastim (Neulasta) is a long-acting form of the growth factor G-CSF, given once per chemotherapy cycle to speed white cell recovery and prevent febrile neutropenia; one dose replaces about eleven daily filgrastim injections. Biosimilars have been sold since 2018 and the Onpro on-body injector delivers it automatically the day after chemotherapy; bone pain is the main side effect.",
    summary: "Pegfilgrastim was approved by the FDA in January 2002 to decrease the incidence of infection manifested by febrile neutropenia in non-myeloid malignancies receiving myelosuppressive chemotherapy, on randomised trials showing a single 6 mg dose per cycle equivalent to about 11 daily filgrastim injections; the EU authorised Neulasta in August 2002 and an acute radiation syndrome indication was added in the US in 2015. It became one of the highest-selling cancer drugs before biosimilars arrived (Fulphila and Udenyca in 2018, Ziextenzo, Nyvepria, Fylnetra, Stimufend and others since), and the Onpro on-body injector avoids a next-day clinic visit. It is not indicated for stem cell mobilisation. Bone pain is the main adverse effect; splenic rupture, capillary leak, aortitis and glomerulonephritis are rare.",
    approvals: [{ region: "US", year: 2002, indication: "Decrease in febrile neutropenia in non-myeloid malignancies on myelosuppressive chemotherapy (acute radiation syndrome added 2015)" }, { region: "US", year: 2018, indication: "First biosimilars (Fulphila, Udenyca); further biosimilars 2019 onwards" }, { region: "EU", year: 2002, indication: "Reduction in duration of neutropenia and febrile neutropenia after cytotoxic chemotherapy (Neulasta); biosimilars from 2018" }],
    companies: ["amgen", "sandoz"], technologies: ["g-csf-growth-factors"], related: ["filgrastim"], links: label("pegfilgrastim", "pegfilgrastim", [{ label: "EPAR", url: EPAR("neulasta") }]), tags: ["nci-list", "supportive"] }),
  d({ id: "epoetin-alfa", name: "Epoetin alfa", brand: "Epogen / Procrit", aka: ["Retacrit (epoetin alfa-epbx)", "Eprex", "Binocrit", "Abseamed"], modality: "Recombinant erythropoietin (erythropoiesis-stimulating agent)", mechanism: "Recombinant human erythropoietin that binds the erythropoietin receptor on erythroid progenitors, stimulating red cell production by the same mechanism as the endogenous hormone.", wikipedia: W("Epoetin_alfa"),
    tldr: "Epoetin alfa is a manufactured version of the kidney hormone that tells the bone marrow to make red blood cells. In cancer it treats anaemia caused by chemotherapy and reduces the need for transfusions, but it is used cautiously because it can shorten survival and cause clots.",
    summary: "Epoetin alfa was approved in June 1989 for anaemia of chronic kidney disease and in 1993 for anaemia due to concomitant myelosuppressive chemotherapy in non-myeloid malignancies when at least two further months of chemotherapy are planned; the biosimilar Retacrit followed in 2018 and the EU authorised the first epoetin biosimilars in 2007. Trials in the 2000s that targeted higher haemoglobin found worse survival and tumour progression in several cancers, leading to boxed warnings, the ESA APPRISE risk programme (2010 to 2017) and the current rule to use the lowest dose that avoids transfusion, never in patients treated with curative intent. Thromboembolism, hypertension and rare pure red cell aplasia are the safety concerns. Darbepoetin alfa is the long-acting alternative.",
    approvals: [{ region: "US", year: 1989, indication: "Anaemia of chronic kidney disease" }, { region: "US", year: 1993, indication: "Anaemia due to concomitant myelosuppressive chemotherapy in non-myeloid malignancies" }, { region: "EU", year: 2007, indication: "First epoetin alfa biosimilars (Binocrit, Abseamed, Epoetin alfa Hexal) including chemotherapy-induced anaemia" }],
    companies: ["amgen", "johnson-johnson", "pfizer"], technologies: ["transfusion-support"], related: ["darbepoetin-alfa"], links: label("epoetin alfa", "epoetinalfa", [{ label: "EPAR (Binocrit)", url: EPAR("binocrit") }]), tags: ["nci-list", "supportive"] }),
  d({ id: "darbepoetin-alfa", name: "Darbepoetin alfa", brand: "Aranesp", modality: "Hyperglycosylated recombinant erythropoietin (erythropoiesis-stimulating agent)", mechanism: "Erythropoietin analogue with two additional N-linked carbohydrate chains that triple its half-life; stimulates the erythropoietin receptor to increase red cell production.", wikipedia: W("Darbepoetin_alfa"),
    tldr: "Darbepoetin alfa (Aranesp) is a longer-acting version of erythropoietin given every one to three weeks to treat anaemia caused by chemotherapy, reducing transfusions but with the same warnings about clots and tumour growth as epoetin.",
    summary: "Darbepoetin alfa was approved by the FDA in September 2001 for anaemia of chronic kidney disease and in July 2002 for anaemia due to concomitant myelosuppressive chemotherapy in non-myeloid malignancies with at least two further months of planned chemotherapy; the EU authorised Aranesp in June 2001. Weekly or three-weekly dosing suited chemotherapy schedules and it displaced much epoetin use in oncology before the survival and thrombosis findings of the 2000s (including the darbepoetin trial in anaemic cancer patients not on chemotherapy, which showed excess mortality) restricted all erythropoiesis-stimulating agents to the lowest dose needed to avoid transfusion in the palliative setting. The label states it has not been shown to improve quality of life or fatigue. Hypertension, thromboembolism and rare pure red cell aplasia are the main risks.",
    approvals: [{ region: "US", year: 2001, indication: "Anaemia of chronic kidney disease" }, { region: "US", year: 2002, indication: "Anaemia due to concomitant myelosuppressive chemotherapy in non-myeloid malignancies" }, { region: "EU", year: 2001, indication: "Anaemia of chronic renal failure; symptomatic anaemia in adults with non-myeloid malignancies receiving chemotherapy (Aranesp)" }],
    companies: ["amgen"], technologies: ["transfusion-support"], related: ["epoetin-alfa"], links: label("darbepoetin alfa", "darbepoetinalfa", [{ label: "EPAR", url: EPAR("aranesp") }]), tags: ["nci-list", "supportive"] }),
  d({ id: "defibrotide", name: "Defibrotide", brand: "Defitelio", modality: "Polydisperse oligonucleotide mixture (endothelial protectant)", mechanism: "Mixture of single-stranded oligonucleotides from porcine intestinal mucosa that enhances plasmin-mediated fibrinolysis, reduces endothelial activation and protects sinusoidal endothelial cells; the mechanism is not fully elucidated.", wikipedia: W("Defibrotide"),
    tldr: "Defibrotide (Defitelio) is the only approved treatment for hepatic veno-occlusive disease, a life-threatening liver complication of high-dose chemotherapy before stem cell transplant, in patients whose kidneys or lungs are also failing.",
    summary: "Defibrotide was approved by the FDA in March 2016 for adults and children with hepatic veno-occlusive disease (sinusoidal obstruction syndrome) with renal or pulmonary dysfunction after haematopoietic stem cell transplantation, on a phase 3 trial against historical controls in which survival at day 100 was 38% versus 25%, supported by an expanded-access programme of several hundred patients; the EU authorised Defitelio in 2013 for severe VOD after HSCT in patients over one month old. A subsequent phase 3 prophylaxis trial in high-risk patients (HARMONY) did not meet its primary endpoint, so use remains therapeutic. Bleeding is the main risk and it is contraindicated with systemic anticoagulants or thrombolytics. Marketed by Jazz Pharmaceuticals.",
    approvals: [{ region: "US", year: 2016, indication: "Hepatic veno-occlusive disease with renal or pulmonary dysfunction after HSCT, adults and children" }, { region: "EU", year: 2013, indication: "Severe hepatic veno-occlusive disease after HSCT in patients over one month (Defitelio)" }],
    companies: ["jazz"], technologies: ["allogeneic-hsct", "autologous-stem-cell-transplant"], links: label("defibrotide", "defibrotide-sodium", [{ label: "EPAR", url: EPAR("defitelio") }]), tags: ["nci-list", "supportive"] }),
  d({ id: "methylnaltrexone", name: "Methylnaltrexone", brand: "Relistor", modality: "Peripherally acting mu-opioid receptor antagonist", mechanism: "Quaternary derivative of naltrexone that does not cross the blood-brain barrier; blocks mu-opioid receptors in the gut to reverse opioid-induced constipation without reducing analgesia or precipitating withdrawal.", wikipedia: W("Methylnaltrexone"),
    tldr: "Methylnaltrexone (Relistor) is an injection or tablet that relieves the severe constipation caused by strong painkillers in people with advanced cancer, without blocking the pain relief itself.",
    summary: "Methylnaltrexone was approved by the FDA in April 2008 for opioid-induced constipation in adults with advanced illness receiving palliative care when laxatives have failed, on two randomised placebo-controlled trials in hospice and palliative populations in which about half of patients had a bowel movement within four hours of the first subcutaneous dose versus around 15% on placebo; indications for chronic non-cancer pain and oral tablets followed in 2014 to 2016. The EU authorised Relistor in 2008. It is a standard second-line option in palliative care guidelines after conventional laxatives; naloxegol and naldemedine are oral alternatives. Abdominal pain, flatulence and nausea are common, and gastrointestinal perforation has been reported in patients with structural bowel disease. Marketed by Salix (Bausch Health).",
    approvals: [{ region: "US", year: 2008, indication: "Opioid-induced constipation in advanced illness receiving palliative care (chronic non-cancer pain and oral tablets added 2014 to 2016)" }, { region: "EU", year: 2008, indication: "Opioid-induced constipation in advanced illness receiving palliative care when laxatives are insufficient (Relistor)" }],
    companies: ["bausch-health"], technologies: ["palliative-care", "pain-management"], links: label("methylnaltrexone", "methylnaltrexonebromide", [{ label: "EPAR", url: EPAR("relistor") }]), tags: ["nci-list", "supportive"] }),
  d({ id: "talc-sclerosant", name: "Talc (intrapleural)", brand: "Sclerosol / Sterile Talc Powder / Steritalc", aka: ["Talc slurry", "Talc poudrage"], modality: "Sclerosing agent (intrapleural powder or aerosol)", mechanism: "Sterile asbestos-free magnesium silicate that provokes an inflammatory pleuritis and fibrosis, sealing the visceral and parietal pleura together so that fluid can no longer accumulate.", wikipedia: W("Pleurodesis"),
    tldr: "Sterile talc is puffed or instilled into the chest cavity after fluid is drained to make the lung stick to the chest wall, stopping cancer-related fluid (malignant pleural effusion) from building up again.",
    summary: "Sclerosol intrapleural aerosol was approved by the FDA in December 1997 and sterile talc powder in 2003 to decrease the recurrence of malignant pleural effusion in symptomatic patients after drainage; talc has been the most effective pleurodesis agent in comparative trials and meta-analyses for decades. Poudrage at thoracoscopy and bedside slurry through a chest drain give similar success (TAPPS trial), and indwelling pleural catheters, with or without talc instilled through them (IPC-PLUS), are the main alternative for patients with trapped lung or short prognosis. Graded, large-particle talc is used to avoid the acute respiratory distress syndrome reported with small-particle preparations. Fever and chest pain after the procedure are expected.",
    approvals: [{ region: "US", year: 1997, indication: "Prevention of recurrence of malignant pleural effusion after drainage (Sclerosol aerosol; sterile powder 2003)" }],
    cancers: ["nsclc", "breast-hr-positive", "mesothelioma", "ovarian"], technologies: ["palliative-care"], links: label("talc", "talc"), tags: ["nci-list", "supportive"] }),
  d({ id: "hpv-bivalent-vaccine", name: "HPV bivalent vaccine (types 16 and 18)", brand: "Cervarix", modality: "Recombinant virus-like particle vaccine (adjuvanted)", mechanism: "L1 capsid virus-like particles of HPV types 16 and 18 with the AS04 adjuvant induce neutralising antibodies that prevent persistent infection with the two types responsible for about 70% of cervical cancers.", wikipedia: W("Cervarix"),
    tldr: "Cervarix is a vaccine against HPV types 16 and 18, the two types that cause most cervical cancers, authorised in the EU in 2007 and the US in 2009 after the 18,000-woman PATRICIA trial showed near-complete protection against type-specific precancer. GSK withdrew it from the US in 2016, but it remains WHO-prequalified and used in national programmes, including single-dose schedules.",
    summary: "The bivalent HPV vaccine was authorised in the EU in September 2007 and approved by the FDA in October 2009 for prevention of cervical cancer, cervical intraepithelial neoplasia and adenocarcinoma in situ caused by HPV 16 and 18 in females aged 9 to 25 (10 to 25 in the US), on the PATRICIA phase 3 trial of more than 18,000 women, which showed near-complete protection against type-specific CIN2+ in HPV-naive women and cross-protection against types 31, 33 and 45. GSK withdrew it from the US market in 2016 for commercial reasons; it remains WHO-prequalified and is used in national programmes, including single-dose schedules supported by the KEN SHE trial and the Costa Rica Vaccine Trial follow-up. Injection-site pain and fatigue are the main adverse effects.",
    approvals: [{ region: "EU", year: 2007, indication: "Prevention of premalignant cervical lesions and cervical cancer caused by HPV 16 and 18 from age 9 (Cervarix); anal lesions added later" }, { region: "US", year: 2009, indication: "Prevention of cervical cancer and precursor lesions caused by HPV 16 and 18 in females 10 to 25 (discontinued in the US 2016)" }],
    cancers: ["cervical"], companies: ["gsk"], technologies: ["hpv-vaccine", "interception-vaccination"], related: ["gardasil-9", "hpv-quadrivalent-vaccine"], links: label("Cervarix", "recombinant-hpv-bivalent-vaccine", [{ label: "EPAR", url: EPAR("cervarix") }]), tags: ["nci-list", "prevention"] }),
  d({ id: "hpv-quadrivalent-vaccine", trials: ["nct04422366", "nct06465914"], name: "HPV quadrivalent vaccine (types 6, 11, 16 and 18)", brand: "Gardasil", aka: ["Silgard"], modality: "Recombinant virus-like particle vaccine", mechanism: "L1 virus-like particles of HPV types 6, 11, 16 and 18 on an aluminium adjuvant induce neutralising antibodies that prevent the infections behind most cervical, anal, vulvar and vaginal cancers and genital warts.", wikipedia: W("Gardasil"),
    tldr: "Gardasil was the first HPV vaccine, licensed in 2006 to prevent cervical and other genital cancers and genital warts. It has been replaced in most countries by the nine-type version, Gardasil 9.",
    summary: "The quadrivalent HPV vaccine was approved by the FDA in June 2006 for females aged 9 to 26 to prevent cervical, vulvar and vaginal cancers and precancers and genital warts caused by HPV 6, 11, 16 and 18, on the FUTURE I and II trials, with males (2009) and anal cancer prevention (2010) added; the EU authorised Gardasil in September 2006. It was the first vaccine indicated to prevent a cancer, and population data from Australia, Scandinavia and the UK have since shown large falls in cervical precancer and invasive cancer in vaccinated cohorts. Gardasil 9, covering five further oncogenic types, replaced it in the US in 2017 and in most programmes since. Syncope after injection and injection-site reactions are the main adverse effects; extensive surveillance has found no link to autoimmune disease.",
    approvals: [{ region: "US", year: 2006, indication: "Prevention of cervical, vulvar and vaginal cancers and precancers and genital warts caused by HPV 6, 11, 16 and 18 in females 9 to 26 (males 2009; anal cancer 2010); superseded by Gardasil 9" }, { region: "EU", year: 2006, indication: "Prevention of premalignant genital lesions, cervical cancer and genital warts from age 9 (Gardasil); anal lesions and cancer added later" }],
    cancers: ["cervical", "vulvar", "anal"], companies: ["merck"], technologies: ["hpv-vaccine", "interception-vaccination"], related: ["gardasil-9", "hpv-bivalent-vaccine"], links: label("Gardasil", "recombinant-hpv-quadrivalent-vaccine", [{ label: "EPAR", url: EPAR("gardasil") }]), tags: ["nci-list", "prevention"] }),
];

// =====================================================================================
// Batch 4: EMA-authorised oncology medicines (ATC L01/L02 and oncology supportive care) absent from the NCI list
// =====================================================================================
const emaLabel = (slug: string, extra: Array<{ label: string; url: string }> = []) => [{ label: "EPAR (EMA)", url: EPAR(slug) }, ...extra];

const batch4: DrugInput[] = [
  d({ id: "mirdametinib", name: "Mirdametinib", brand: "Gomekli / Ezmekly", aka: ["PD-0325901"], modality: "Small-molecule allosteric MEK1/2 inhibitor", mechanism: "Non-ATP-competitive MEK1/2 inhibitor that penetrates the CNS; lowers ERK signalling in NF1-deficient Schwann-lineage cells driving plexiform neurofibromas.", wikipedia: W("Mirdametinib"),
    tldr: "Mirdametinib (Gomekli in the US, Ezmekly in Europe) is a MEK-blocking capsule or dispersible tablet for adults and children with neurofibromatosis type 1 whose plexiform neurofibromas cannot be removed surgically; it is the first such drug approved for adults.",
    summary: "Mirdametinib was approved by the FDA in February 2025 for adults and children aged 2 and over with NF1 and symptomatic plexiform neurofibromas not amenable to complete resection, on the ReNeu phase 2b trial in which 41% of adults and 52% of children had a confirmed objective response by central review, with deep and durable responses and improvement in pain. The European Commission granted a conditional marketing authorisation for Ezmekly in July 2025 for the same population. It is the first MEK inhibitor approved for adults with this benign but disabling tumour (selumetinib covered children first). Rash, diarrhoea, nausea, musculoskeletal pain, reduced ejection fraction and ocular toxicity are class effects. Developed by SpringWorks Therapeutics, acquired by Merck KGaA in 2025.",
    approvals: [{ region: "US", year: 2025, indication: "NF1 with symptomatic plexiform neurofibromas not amenable to complete resection, adults and children 2 and over (Gomekli)" }, { region: "EU", year: 2025, indication: "Symptomatic, inoperable plexiform neurofibromas in NF1, age 2 and over (Ezmekly, conditional)" }],
    targets: ["mek"], companies: ["springworks"], technologies: ["kinase-inhibitors"], pathways: ["ras-mapk"], related: ["selumetinib"], links: emaLabel("ezmekly", [{ label: "US label (DailyMed)", url: DM("mirdametinib") }]), tags: ["ema-list"], notes: ["NF1 plexiform neurofibroma is a benign tumour with no cancer record; not linked to a cancer id."] }),
  d({ id: "catumaxomab", name: "Catumaxomab", brand: "Korjuny", aka: ["Removab (2009 to 2017)"], modality: "Trifunctional bispecific antibody (EpCAM x CD3, rat-mouse hybrid)", mechanism: "Binds EpCAM on tumour cells and CD3 on T cells while its Fc region engages Fc-gamma receptor-positive accessory cells, killing EpCAM-positive cells in the peritoneal cavity by T-cell cytotoxicity, phagocytosis and antibody-dependent mechanisms.", wikipedia: W("Catumaxomab"),
    tldr: "Catumaxomab (Korjuny) is an antibody infused into the abdominal cavity to control malignant ascites, the build-up of fluid caused by cancers such as ovarian and stomach cancer, in people who have run out of other treatments.",
    summary: "Catumaxomab was the first bispecific antibody approved anywhere, authorised in the EU in 2009 as Removab for malignant ascites in EpCAM-positive carcinomas on a randomised trial against paracentesis alone in which puncture-free survival was quadrupled. Its marketing authorisation was withdrawn in 2017 for commercial reasons after the original company failed, and a new authorisation was granted to Korjuny in February 2025 for intraperitoneal treatment of malignant ascites in adults with EpCAM-positive carcinomas not eligible for further systemic anticancer therapy. It is given as four intraperitoneal infusions over about ten days. Cytokine release-type reactions (fever, nausea, vomiting, abdominal pain) are almost universal and hepatic enzyme rises are common; it has never been approved in the US.",
    approvals: [{ region: "EU", year: 2009, indication: "Malignant ascites in EpCAM-positive carcinomas when standard therapy is unavailable (Removab; withdrawn 2017)" }, { region: "EU", year: 2025, indication: "Intraperitoneal treatment of malignant ascites in adults with EpCAM-positive carcinomas not eligible for further systemic therapy (Korjuny)" }],
    targets: ["epcam", "cd3"], cancers: ["ovarian", "gastric", "pancreatic", "colorectal"], technologies: ["bispecific-antibody", "t-cell-engager"], links: emaLabel("korjuny"), tags: ["ema-list", "supportive"] }),
  d({ id: "efbemalenograstim-alfa", name: "Efbemalenograstim alfa", brand: "Ryzneuta", aka: ["F-627"], modality: "Long-acting recombinant G-CSF dimer (Fc fusion)", mechanism: "Two G-CSF molecules fused to a human IgG2 Fc fragment; Fc-mediated recycling prolongs the half-life so that a single dose per chemotherapy cycle stimulates neutrophil production and release.", wikipedia: W("Efbemalenograstim_alfa"),
    tldr: "Efbemalenograstim alfa (Ryzneuta) is a once-per-cycle white cell booster, an alternative to pegfilgrastim, that reduces the risk of febrile infections after chemotherapy.",
    summary: "Efbemalenograstim alfa was approved by the FDA in November 2023 to decrease the incidence of infection manifested by febrile neutropenia in adults with non-myeloid malignancies receiving myelosuppressive chemotherapy, and by the European Commission in March 2024 for reduction of the duration of neutropenia and incidence of febrile neutropenia after cytotoxic chemotherapy (excluding CML and MDS). Two phase 3 trials in breast cancer patients receiving docetaxel-cyclophosphamide showed a duration of severe neutropenia comparable to pegfilgrastim (GC-627-04) and superior to placebo (GC-627-05). Unlike pegylated G-CSF it uses Fc fusion rather than PEG for half-life extension. Bone pain, nausea and thrombocytopenia are the common adverse effects; it is not indicated for stem cell mobilisation.",
    approvals: [{ region: "US", year: 2023, indication: "Decrease in febrile neutropenia in adults with non-myeloid malignancies on myelosuppressive chemotherapy" }, { region: "EU", year: 2024, indication: "Reduction in duration of neutropenia and febrile neutropenia after cytotoxic chemotherapy in adults (excluding CML and MDS)" }],
    companies: ["evive-biotech"], technologies: ["g-csf-growth-factors"], related: ["pegfilgrastim", "filgrastim"], links: emaLabel("ryzneuta", [{ label: "US label (DailyMed)", url: DM("efbemalenograstim") }]), tags: ["ema-list", "supportive"] }),
  d({ id: "padeliporfin", name: "Padeliporfin", brand: "Tookad", aka: ["WST11", "Padeliporfin di-potassium", "Vascular-targeted photodynamic therapy (VTP)"], modality: "Intravenous photosensitiser for vascular-targeted photodynamic therapy", mechanism: "Water-soluble bacteriochlorophyll derivative that stays in the circulation; activation by 753 nm laser light delivered through transperineal fibres generates oxygen radicals that occlude tumour vasculature and cause focal necrosis of the treated prostate lobe.", wikipedia: W("Padeliporfin"),
    tldr: "Tookad is a light-activated drug for men with low-risk prostate cancer in one side of the prostate. It is infused and then switched on with laser fibres placed in the gland, destroying the cancer-bearing tissue as an alternative to watchful waiting.",
    summary: "Padeliporfin was authorised in the EU in November 2017 as monotherapy for previously untreated, unilateral, low-risk prostate adenocarcinoma (stage T1c or T2a, Gleason 6, PSA 10 ng/mL or below) in men with a life expectancy of at least 10 years, on the PCM301 phase 3 trial in which vascular-targeted photodynamic therapy roughly halved progression and the need for radical therapy compared with active surveillance, at the cost of transient urinary and erectile symptoms. It is the only focal drug-device therapy for prostate cancer with a marketing authorisation; an FDA advisory committee questioned its benefit over surveillance and it is not approved in the US. Trials in intermediate-risk disease and in upper urinary tract urothelial cancer are ongoing. Dysuria, haematuria and erectile dysfunction are the main adverse effects and patients must avoid light exposure for 48 hours.",
    approvals: [{ region: "EU", year: 2017, indication: "Unilateral, low-risk, previously untreated prostate adenocarcinoma in men with life expectancy of at least 10 years (Tookad VTP)" }],
    cancers: ["prostate"], technologies: ["active-surveillance"], links: emaLabel("tookad"), tags: ["ema-list"], terms: ["active-surveillance-term"] }),
  d({ id: "telotristat-ethyl", name: "Telotristat ethyl", brand: "Xermelo", aka: ["LX1032", "Telotristat etiprate"], modality: "Oral tryptophan hydroxylase inhibitor", mechanism: "Prodrug of telotristat, which inhibits tryptophan hydroxylase, the rate-limiting enzyme of peripheral serotonin synthesis in neuroendocrine tumour cells, lowering urinary 5-HIAA and bowel frequency without crossing into the brain.", wikipedia: W("Telotristat_ethyl"),
    tldr: "Telotristat ethyl (Xermelo) is a tablet that cuts the serotonin that neuroendocrine tumours pour out, easing the relentless diarrhoea of carcinoid syndrome when somatostatin analogue injections are not enough.",
    summary: "Telotristat ethyl was approved by the FDA in February 2017 and authorised in the EU in September 2017 for carcinoid syndrome diarrhoea in combination with somatostatin analogue therapy in adults inadequately controlled by that therapy, on the TELESTAR phase 3 trial (135 patients) in which the 250 mg three-times-daily dose reduced daily bowel movements more than placebo, a statistically significant difference, and lowered urinary 5-HIAA. It is the first oral drug for carcinoid syndrome and the first tryptophan hydroxylase inhibitor approved for any indication. Nausea, headache, raised liver enzymes, depression and constipation are the main adverse effects. Marketed by TerSera in the US and SERB in Europe.",
    approvals: [{ region: "US", year: 2017, indication: "Carcinoid syndrome diarrhoea with somatostatin analogue therapy in adults inadequately controlled by SSA alone" }, { region: "EU", year: 2017, indication: "Same (Xermelo)" }],
    cancers: ["neuroendocrine"], companies: ["tersera-therapeutics", "serb-pharmaceuticals"], related: ["octreotide-lanreotide"], links: emaLabel("xermelo", [{ label: "US label (DailyMed)", url: DM("telotristat") }]), tags: ["ema-list", "supportive"] }),
  d({ id: "lipegfilgrastim", name: "Lipegfilgrastim", brand: "Lonquex", modality: "Glycopegylated recombinant G-CSF", mechanism: "Filgrastim site-specifically glycopegylated at threonine 134; reduced renal clearance gives once-per-cycle dosing with neutrophil-mediated self-regulating elimination.", wikipedia: W("Lipegfilgrastim"),
    tldr: "Lipegfilgrastim (Lonquex) is a once-per-chemotherapy-cycle white cell booster used in Europe, similar to pegfilgrastim, for adults and children from two years old.",
    summary: "Lipegfilgrastim was authorised by the European Commission in July 2013 for reduction in the duration of neutropenia and the incidence of febrile neutropenia in adults treated with cytotoxic chemotherapy for malignancy (excluding CML and MDS), extended to children aged 2 and over in 2021, on phase 3 trials in breast cancer (non-inferior duration of severe neutropenia versus pegfilgrastim) and NSCLC (superior to placebo). It differs from pegfilgrastim in the site-specific enzymatic glycopegylation used to attach the polyethylene glycol chain. It is not approved in the US. Bone pain and musculoskeletal pain are the common adverse effects; splenic rupture and pulmonary adverse reactions are rare class risks. Marketed by Teva.",
    approvals: [{ region: "EU", year: 2013, indication: "Reduction in duration of neutropenia and febrile neutropenia after cytotoxic chemotherapy in adults (children from 2 years added 2021)" }],
    companies: ["teva"], technologies: ["g-csf-growth-factors"], related: ["pegfilgrastim"], links: emaLabel("lonquex"), tags: ["ema-list", "supportive"] }),
  d({ id: "tegafur-gimeracil-oteracil", name: "Tegafur, gimeracil and oteracil (S-1)", brand: "Teysuno", aka: ["S-1", "TS-1"], modality: "Oral fluoropyrimidine combination (antimetabolite)", mechanism: "Tegafur is a fluorouracil prodrug; gimeracil inhibits dihydropyrimidine dehydrogenase to sustain fluorouracil levels, and oteracil blocks phosphorylation of fluorouracil in the gut to reduce diarrhoea.", wikipedia: W("Tegafur/gimeracil/oteracil"),
    tldr: "Teysuno (S-1) is an oral chemotherapy combining a fluorouracil pro-drug with two protectors. It is a standard in Japan and approved in Europe for stomach cancer with cisplatin and for bowel cancer when other fluoropyrimidines cause hand-foot syndrome or heart problems.",
    summary: "S-1 has been a mainstay of gastric, pancreatic, colorectal and lung cancer treatment in Japan since 1999 (ACTS-GC established adjuvant S-1 in gastric cancer). The European Commission authorised Teysuno in March 2011 for advanced gastric cancer with cisplatin, on the FLAGS trial in which S-1 plus cisplatin was non-inferior to fluorouracil plus cisplatin with less toxicity, and in 2022 for metastatic colorectal cancer as monotherapy or with oxaliplatin or irinotecan, with or without bevacizumab, in patients who cannot continue another fluoropyrimidine because of hand-foot syndrome or cardiovascular toxicity. Because Western patients metabolise tegafur faster through CYP2A6 polymorphisms, doses differ from Japan. It is not approved in the US, where a trial of S-1 versus fluorouracil failed to show superiority. Diarrhoea, neutropenia and stomatitis are the main toxicities.",
    approvals: [{ region: "JP", year: 1999, indication: "Gastric cancer; later colorectal, head and neck, lung, pancreatic, biliary and breast cancer (TS-1)" }, { region: "EU", year: 2011, indication: "Advanced gastric cancer with cisplatin; metastatic colorectal cancer intolerant of other fluoropyrimidines added 2022 (Teysuno)" }],
    cancers: ["gastric", "colorectal", "pancreatic"], companies: ["taiho"], technologies: ["cytotoxic-chemotherapy"], related: ["fluorouracil", "capecitabine"], links: emaLabel("teysuno"), tags: ["ema-list"], terms: ["prodrug"] }),
  d({ id: "vinflunine", trials: ["nct07419295"], name: "Vinflunine", brand: "Javlor", modality: "Fluorinated vinca alkaloid (microtubule inhibitor)", mechanism: "Third-generation vinca alkaloid that binds tubulin with lower affinity than vinorelbine, suppressing microtubule dynamics and causing mitotic arrest; less neurotoxic than earlier vincas.", wikipedia: W("Vinflunine"),
    tldr: "Vinflunine (Javlor) is a chemotherapy infusion used in Europe as a second treatment for advanced bladder cancer after platinum chemotherapy has stopped working.",
    summary: "Vinflunine was authorised by the European Commission in September 2009 as monotherapy for advanced or metastatic transitional cell carcinoma of the urothelial tract after failure of a prior platinum-containing regimen, on a phase 3 trial of 370 patients against best supportive care in which median overall survival improved modestly, a statistically significant difference in the eligible population, making it the first drug with level 1 evidence in second-line urothelial cancer. It is not approved in the US, where the FDA declined the application. Pembrolizumab, enfortumab vedotin and erdafitinib have since displaced it in most guidelines, but it remains an option where immunotherapy is unsuitable. Neutropenia, constipation (prophylactic laxatives are recommended), fatigue and QT prolongation are the main adverse effects. Marketed by Pierre Fabre.",
    approvals: [{ region: "EU", year: 2009, indication: "Advanced or metastatic transitional cell carcinoma of the urothelial tract after failure of a platinum-containing regimen" }],
    cancers: ["urothelial"], companies: ["pierre-fabre"], technologies: ["cytotoxic-chemotherapy"], related: ["vinorelbine", "vinblastine"], links: emaLabel("javlor"), tags: ["ema-list"] }),
  d({ id: "histamine-dihydrochloride", name: "Histamine dihydrochloride", brand: "Ceplene", modality: "Immunomodulator (H2 receptor agonist) given with interleukin-2", mechanism: "Inhibits NADPH oxidase in monocytes and macrophages via H2 receptors, reducing the reactive oxygen species that inactivate NK and T cells and thereby protecting IL-2-activated lymphocytes in the leukaemic microenvironment.", wikipedia: W("Histamine_dihydrochloride"),
    tldr: "Ceplene is a twice-daily injection of histamine given alongside low-dose interleukin-2 as maintenance treatment for adults with acute myeloid leukaemia in first remission, to help immune cells prevent relapse. It is authorised in Europe only.",
    summary: "Histamine dihydrochloride was authorised in the EU in October 2008 under exceptional circumstances, with low-dose interleukin-2, as maintenance therapy for adults with acute myeloid leukaemia in first complete remission, on a phase 3 trial of 320 patients in which the combination improved leukaemia-free survival compared with no maintenance; the label notes efficacy is not fully established over age 60 and an FDA application was not approvable in 2000. It is one of the very few approved maintenance immunotherapies in AML, though oral azacitidine (Onureg) and FLT3 inhibitors now fill that space, and it is little used. Flushing, headache, hypotension and injection-site reactions occur with each histamine dose.",
    approvals: [{ region: "EU", year: 2008, indication: "Maintenance with interleukin-2 for adults with AML in first remission (exceptional circumstances)" }],
    cancers: ["aml"], technologies: ["cytokine-therapy"], related: ["aldesleukin"], links: emaLabel("ceplene"), tags: ["ema-list"] }),
  d({ id: "anagrelide", trials: ["nct04285086"], name: "Anagrelide", brand: "Agrylin / Xagrid", modality: "Oral platelet-lowering agent (imidazoquinazoline)", mechanism: "Inhibits megakaryocyte maturation and platelet production, probably through phosphodiesterase 3 inhibition and effects on megakaryocyte post-mitotic development; does not affect white cells.", wikipedia: W("Anagrelide"),
    tldr: "Anagrelide (Agrylin) is a capsule that lowers dangerously high platelet counts in essential thrombocythaemia and other myeloproliferative neoplasms, reducing the risk of clots and bleeding.",
    summary: "Anagrelide was approved by the FDA in March 1997 for thrombocythaemia secondary to myeloproliferative neoplasms, to reduce elevated platelet counts and the risk of thrombosis and to ameliorate thrombo-haemorrhagic symptoms, on open-label studies in which the majority of patients achieved platelet responses; the EU authorised Xagrid in November 2004 as second-line therapy for at-risk essential thrombocythaemia patients intolerant of or not adequately controlled by their current therapy. The UK PT-1 trial found hydroxyurea plus aspirin superior to anagrelide plus aspirin for arterial thrombosis and myelofibrotic transformation, so hydroxycarbamide remains first line and anagrelide is used in younger patients or when hydroxycarbamide fails. Palpitations, headache, fluid retention and, rarely, cardiomyopathy are the main adverse effects.",
    approvals: [{ region: "US", year: 1997, indication: "Thrombocythaemia secondary to myeloproliferative neoplasms" }, { region: "EU", year: 2004, indication: "Elevated platelet counts in at-risk essential thrombocythaemia intolerant of or inadequately controlled by current therapy (Xagrid)" }],
    cancers: ["myeloproliferative-neoplasms", "essential-thrombocythaemia"], companies: ["takeda"], related: ["hydroxyurea"], links: emaLabel("xagrid", [{ label: "US label (DailyMed)", url: DM("anagrelide") }]), tags: ["ema-list"] }),
  d({ id: "temoporfin", name: "Temoporfin", brand: "Foscan", aka: ["mTHPC", "meta-tetra(hydroxyphenyl)chlorin"], modality: "Intravenous photosensitiser for photodynamic therapy", mechanism: "Chlorin photosensitiser that accumulates in tumour tissue and, on illumination with 652 nm laser light four days after injection, generates singlet oxygen that causes tumour necrosis and vascular shutdown.", wikipedia: W("Temoporfin"),
    tldr: "Foscan is a light-activated drug used in Europe to shrink advanced head and neck cancers that have failed other treatments and cannot be operated on, irradiated or given chemotherapy, to relieve symptoms.",
    summary: "Temoporfin was authorised by the European Commission in October 2001 for palliative treatment of advanced head and neck squamous cell carcinoma failing prior therapies and unsuitable for radiotherapy, surgery or systemic chemotherapy, on open-label phase 2 studies in which a proportion of patients achieved local tumour responses and symptom relief. It is a second-generation photosensitiser with a shorter photosensitivity period than porfimer sodium (Photofrin), the first-generation agent approved in the US for oesophageal and lung cancer, but patients must still avoid bright light for about two weeks. The FDA did not approve it. Pain at the treated site, local swelling and skin photosensitivity are the main adverse effects. Marketed by biolitec.",
    approvals: [{ region: "EU", year: 2001, indication: "Palliative treatment of advanced head and neck squamous cell carcinoma failing prior therapy and unsuitable for radiotherapy, surgery or chemotherapy" }],
    cancers: ["head-and-neck"], companies: ["biolitec"], links: emaLabel("foscan"), tags: ["ema-list"] }),
  d({ id: "thyrotropin-alfa", name: "Thyrotropin alfa", brand: "Thyrogen", aka: ["Recombinant human TSH", "rhTSH"], modality: "Recombinant human thyroid-stimulating hormone", mechanism: "Recombinant TSH stimulates iodine uptake and thyroglobulin release from thyroid remnants and differentiated thyroid cancer cells, allowing radioiodine ablation and thyroglobulin testing without stopping levothyroxine.", wikipedia: W("Thyrotropin_alfa"),
    tldr: "Thyrogen is an injected version of thyroid-stimulating hormone that lets people with thyroid cancer have radioiodine treatment and follow-up blood tests without stopping their thyroid hormone tablets and suffering weeks of hypothyroidism.",
    summary: "Thyrotropin alfa was approved by the FDA in November 1998 as an adjunctive diagnostic tool for serum thyroglobulin testing with or without radioiodine imaging in the follow-up of well-differentiated thyroid cancer, and in 2007 for pre-therapeutic stimulation before radioiodine remnant ablation after thyroidectomy in patients without distant metastases; the EU authorised Thyrogen in 2000 with the same uses. The HiLo and ESTIMABL trials showed that rhTSH-stimulated low-dose (1.1 GBq) radioiodine ablation is as effective as high-dose ablation after thyroid hormone withdrawal, sparing patients hypothyroid symptoms and reducing radiation exposure. Nausea and headache are the main adverse effects; transient tumour swelling can occur with CNS or spinal metastases. Marketed by Sanofi (Genzyme).",
    approvals: [{ region: "US", year: 1998, indication: "Adjunctive diagnostic tool for thyroglobulin testing in well-differentiated thyroid cancer; pre-therapeutic stimulation for radioiodine remnant ablation added 2007" }, { region: "EU", year: 2000, indication: "Thyroglobulin testing and radioiodine imaging in thyroid cancer follow-up; pre-therapeutic stimulation for radioiodine ablation" }],
    cancers: ["thyroid"], companies: ["sanofi"], technologies: ["radioiodine-therapy"], links: emaLabel("thyrogen", [{ label: "US label (DailyMed)", url: DM("thyrotropin alfa") }]), tags: ["ema-list", "supportive"], terms: ["radioiodine-term"] }),
  d({ id: "tasonermin", name: "Tasonermin", brand: "Beromun", aka: ["Recombinant TNF-alpha-1a", "rTNF-alpha"], modality: "Recombinant tumour necrosis factor alpha for isolated limb perfusion", mechanism: "Recombinant human TNF-alpha delivered with melphalan under mild hyperthermia to an isolated limb circulation; disrupts tumour vasculature and increases melphalan penetration, causing haemorrhagic necrosis of the sarcoma.", wikipedia: W("Tasonermin"),
    tldr: "Beromun is a recombinant form of the immune protein TNF-alpha, pumped with the chemotherapy melphalan through the isolated blood supply of an arm or leg to shrink soft-tissue sarcomas so that the limb can be saved rather than amputated.",
    summary: "Tasonermin was authorised by the European Commission in April 1999 as an adjunct to surgery for irresectable soft-tissue sarcoma of the limbs, with melphalan via mild hyperthermic isolated limb perfusion, to prevent or delay amputation or for palliation, on multicentre European studies in which the majority of patients achieved limb salvage. Systemic TNF-alpha is far too toxic to give intravenously, so the drug exists only for this surgical technique performed in a small number of specialist centres. It is not approved in the US. Regional toxicity (limb oedema, skin reactions, neuropathy) and, if leakage into the systemic circulation occurs, shock are the main risks; the same approach is used for in-transit melanoma.",
    approvals: [{ region: "EU", year: 1999, indication: "Irresectable soft-tissue sarcoma of the limbs with melphalan via isolated limb perfusion, as an adjunct to surgery or for palliation" }],
    cancers: ["sarcoma", "melanoma"], technologies: ["isolated-limb-perfusion", "cytokine-therapy"], related: ["melphalan"], links: emaLabel("beromun"), tags: ["ema-list"], terms: ["limb-salvage-term"] }),
  d({ id: "samarium-153-lexidronam", name: "Samarium-153 lexidronam", brand: "Quadramet", aka: ["153Sm-EDTMP", "Samarium Sm 153 lexidronam pentasodium"], modality: "Bone-seeking therapeutic radiopharmaceutical (beta emitter)", mechanism: "Samarium-153 chelated to the tetraphosphonate EDTMP concentrates in areas of high bone turnover around osteoblastic metastases; beta emission (1.9 day half-life) irradiates the metastases and relieves pain, with gamma emission allowing imaging.", wikipedia: W("Samarium_(153Sm)_lexidronam"),
    tldr: "Quadramet (samarium-153 lexidronam) is a radioactive bone-seeking injection that lodges in bone metastases and irradiates them from inside, approved in 1997 to relieve pain from prostate, breast and other cancers spread to bone. Most patients get relief within one to two weeks, but marrow suppression follows at three to five weeks, and radium-223 and PSMA radioligands have largely replaced it.",
    summary: "Samarium-153 lexidronam was approved by the FDA in March 1997 and authorised in the EU in February 1998 for relief of pain in patients with confirmed osteoblastic metastatic bone lesions that take up technetium-labelled bisphosphonate on bone scan, on placebo-controlled trials in which most patients had pain relief within one to two weeks lasting for months. It and strontium-89 (Metastron) were the bone-pain radiopharmaceuticals of the 1990s; radium-223 (Xofigo), which extends survival in prostate cancer, and PSMA radioligands have since taken most of their role. A single intravenous dose is given; transient marrow suppression, with nadir at three to five weeks, is the main toxicity, and a pain flare can occur early. Distributed by Lantheus in the US and Curium in Europe.",
    approvals: [{ region: "US", year: 1997, indication: "Relief of pain in patients with confirmed osteoblastic metastatic bone lesions that enhance on radionuclide bone scan" }, { region: "EU", year: 1998, indication: "Relief of bone pain from multiple painful osteoblastic skeletal metastases (Quadramet)" }],
    cancers: ["prostate", "breast-hr-positive", "nsclc"], companies: ["lantheus", "curium"], technologies: ["radioligand-therapy", "palliative-care"], related: ["radium-223"], links: emaLabel("quadramet", [{ label: "US label (DailyMed)", url: DM("samarium") }]), tags: ["ema-list", "supportive"] }),
  d({ id: "ibandronic-acid", name: "Ibandronic acid", brand: "Bondronat", aka: ["Ibandronate", "Boniva (osteoporosis formulation)", "Bonviva"], modality: "Nitrogen-containing bisphosphonate (intravenous and oral)", mechanism: "Binds bone mineral and inhibits farnesyl pyrophosphate synthase in osteoclasts, suppressing bone resorption and lowering tumour-induced calcium release.", wikipedia: W("Ibandronic_acid"),
    tldr: "Ibandronic acid (Bondronat) is a bisphosphonate available in Europe as a monthly infusion or daily tablet to prevent fractures and other bone complications in women with breast cancer that has spread to bone, and to treat cancer-related high calcium.",
    summary: "Ibandronic acid was authorised by the European Commission in June 1996 for tumour-induced hypercalcaemia and later for prevention of skeletal events (pathological fractures, bone complications requiring radiotherapy or surgery) in patients with breast cancer and bone metastases, on placebo-controlled trials of intravenous 6 mg every three to four weeks and oral 50 mg daily that reduced skeletal morbidity. It is the only bisphosphonate with an oral formulation licensed for bone metastases; in the US ibandronate (Boniva) is approved for osteoporosis only. The ZICE trial found oral ibandronate slightly less effective than zoledronic acid for skeletal events, so guidelines list it as an alternative. Renal toxicity is lower than with zoledronic acid; osteonecrosis of the jaw and oesophageal irritation with tablets are the recognised risks. Originated by Roche.",
    approvals: [{ region: "EU", year: 1996, indication: "Tumour-induced hypercalcaemia; prevention of skeletal events in breast cancer with bone metastases (Bondronat)" }],
    cancers: ["breast-hr-positive"], companies: ["roche-genentech"], technologies: ["bone-modifying-agents"], related: ["zoledronic-acid", "denosumab"], links: emaLabel("bondronat"), tags: ["ema-list", "supportive"] }),
  d({ id: "dorocubicel", name: "Dorocubicel (UM171-expanded cord blood)", brand: "Zemcelpro", aka: ["UM171 cell therapy", "ECT-001"], modality: "Allogeneic expanded cord blood cell therapy (ATMP)", mechanism: "CD34-positive cord blood cells expanded ex vivo for seven days with the small molecule UM171, which preserves haematopoietic stem cell self-renewal, co-infused with the non-expanded CD34-negative fraction to reconstitute haematopoiesis after myeloablative conditioning.", wikipedia: W("Cord_blood"),
    tldr: "Zemcelpro is a laboratory-expanded umbilical cord blood transplant for adults with blood cancers who need a donor stem cell transplant but have no suitable matched donor; expanding the cells lets a single small cord blood unit be enough.",
    summary: "Dorocubicel was authorised by the European Commission in August 2025 as an advanced therapy medicinal product for adults with haematological malignancies requiring allogeneic haematopoietic stem cell transplantation after myeloablative conditioning for whom no other suitable donor cells are available. It consists of the CD34-positive fraction of a single cord blood unit expanded with UM171, a pyrimidoindole agonist of stem cell self-renewal discovered at Universite de Montreal, together with the unexpanded CD34-negative cells. Phase 2 studies showed faster neutrophil engraftment than historical unmanipulated cord blood and low rates of severe chronic graft-versus-host disease, addressing the slow engraftment that limited cord blood transplants in adults. It is not approved in the US. Risks are those of allogeneic transplantation: infection, graft failure and graft-versus-host disease. Developed by ExCellThera.",
    approvals: [{ region: "EU", year: 2025, indication: "Adults with haematological malignancies requiring allogeneic HSCT after myeloablative conditioning with no other suitable donor cells" }],
    cancers: ["aml", "all-leukemia", "mds"], technologies: ["allogeneic-hsct", "allogeneic-cell-therapy"], links: emaLabel("zemcelpro"), tags: ["ema-list"] }),
];

export const approvedWave1: DrugInput[] = [...batch1, ...batch2, ...batch3, ...batch4];
